const lessons = [
{num:1,time:"00:00:30,000 --> 00:00:34,539",arabic:"لَنْ يَجِدَ أَمِيرُ الْمُؤْمِنِينَ خَيْرًا مِنْكَ لِتَحَمُّلِ هَذِهِ الْمَسْؤُولِيَّةِ.",segs:[{ar:"لَنْ يَجِدَ أَمِيرُ الْمُؤْمِنِينَ",uz:"Mo‘minlar amiri topa olmaydi"},{ar:"خَيْرًا مِنْكَ",uz:"sizdan yaxshiroq kishini"},{ar:"لِتَحَمُّلِ هَذِهِ الْمَسْؤُولِيَّةِ",uz:"bu mas’uliyatni zimmasiga olish uchun"}],full_uz:"Mo‘minlar amiri bu mas’uliyatni zimmasiga olish uchun sizdan yaxshiroq kishini topa olmaydi.",note:"تَحَمُّلُ الْمَسْؤُولِيَّةِ — «mas’uliyatni zimmasiga olish»."},
{num:2,time:"00:00:34,539 --> 00:00:37,000",arabic:"غَفَرَ اللَّهُ لَكَ.",segs:null,full_uz:"Alloh sizni mag‘firat qilsin.",note:null},
{num:3,time:"00:00:37,640 --> 00:00:39,579",arabic:"إِنَّمَا جِئْتُ لِأَقْتَبِسَ مِنْكَ الْعِلْمَ.",segs:[{ar:"إِنَّمَا جِئْتُ",uz:"Men faqat keldim"},{ar:"لِأَقْتَبِسَ مِنْكَ الْعِلْمَ",uz:"sizdan ilm olish uchun"}],full_uz:"Men faqat sizdan ilm olish uchun keldim.",note:"اِقْتَبَسَ الْعِلْمَ — «ilm olmoq, ilmidan bahramand bo‘lmoq»."},
{num:4,time:"00:00:39,579 --> 00:00:43,000",arabic:"وَأَنْتَ تَأْمُرُنِي أَنْ أَرْحَلَ عَنْكَ لِأَتَوَلَّى الْقَضَاءَ.",segs:[{ar:"وَأَنْتَ تَأْمُرُنِي",uz:"Siz esa menga buyuryapsiz"},{ar:"أَنْ أَرْحَلَ عَنْكَ",uz:"huzuringizdan ketishimni"},{ar:"لِأَتَوَلَّى الْقَضَاءَ",uz:"qozilikni zimmasiga olish uchun"}],full_uz:"Siz esa qozilikni zimmasiga olishim uchun huzuringizdan ketishimni buyuryapsiz.",note:"تَوَلَّى الْقَضَاءَ — «qozilik lavozimini egallamoq»."},
{num:5,time:"00:00:43,920 --> 00:00:47,340",arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.",segs:[{ar:"لَا حَوْلَ وَلَا قُوَّةَ",uz:"Hech qanday qudrat va kuch yo‘q"},{ar:"إِلَّا بِاللَّهِ",uz:"faqat Alloh bilangina bor"}],full_uz:"Kuch va qudrat faqat Alloh bilandir.",note:null},
{num:6,time:"00:00:49,719 --> 00:00:54,039",arabic:"إِنْ سَمِعْتُ هَذَا مِنْكَ لَنْ تَرَانِي ثَانِيَةً.",segs:[{ar:"إِنْ سَمِعْتُ هَذَا مِنْكَ",uz:"Agar buni sizdan eshitsam"},{ar:"لَنْ تَرَانِي ثَانِيَةً",uz:"meni boshqa ko‘rmaysiz"}],full_uz:"Agar buni sizdan eshitsam, meni boshqa ko‘rmaysiz.",note:null},
{num:7,time:"00:00:54,039 --> 00:00:58,920",arabic:"أَرَأَيْتَ إِلَى أَيْنَ وَصَلَتْ بِنَا الْأُمُورُ يَا أَبَا الْعَبَّاسِ؟",segs:[{ar:"أَرَأَيْتَ",uz:"Ko‘rdingizmi"},{ar:"إِلَى أَيْنَ وَصَلَتْ بِنَا الْأُمُورُ",uz:"ishlar bizni qayerga olib kelganini"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abul Abbos?"}],full_uz:"Ishlar bizni qayerga olib kelganini ko‘rdingizmi, ey Abul Abbos?",note:null},
{num:8,time:"00:01:00,000 --> 00:01:03,280",arabic:"صِرْنَا نُقَاتِلُ بَعْضُنَا بَعْضًا.",segs:null,full_uz:"Bir-birimizga qarshi jang qiladigan bo‘ldik.",note:"صَارَ + muzori’ — yangi holatga o‘tishni bildiradi: «...qiladigan bo‘ldi»."},
{num:9,time:"00:01:03,280 --> 00:01:08,099",arabic:"أَثَمَّ شَرٌّ أَكْبَرُ مِنْ أَنْ يَتَقَاتَلَ الْمُسْلِمُونَ فِيمَا بَيْنَهُمْ؟",segs:[{ar:"أَثَمَّ شَرٌّ أَكْبَرُ",uz:"Kattaroq yomonlik bormi"},{ar:"مِنْ أَنْ يَتَقَاتَلَ الْمُسْلِمُونَ",uz:"musulmonlarning jang qilishidan"},{ar:"فِيمَا بَيْنَهُمْ",uz:"o‘zaro?"}],full_uz:"Musulmonlarning o‘zaro jang qilishidan kattaroq yomonlik bormi?",note:"ثَمَّ — «bor, mavjud»; ثُمَّ («so‘ng») bilan farqlanadi. يَتَقَاتَلُ o‘zaro jang qilishni bildiradi."},
{num:10,time:"00:01:08,099 --> 00:01:13,680",arabic:"تَارِكِينَ أَعْدَاءَهُمْ عَلَى الثُّغُورِ يَشْمَتُونَ بِهِمْ وَيَسْخَرُونَ مِنْ جَهَالَتِهِمْ.",segs:[{ar:"تَارِكِينَ أَعْدَاءَهُمْ",uz:"Dushmanlarini qoldirib"},{ar:"عَلَى الثُّغُورِ",uz:"chegara hududlarida"},{ar:"يَشْمَتُونَ بِهِمْ",uz:"ularning boshiga tushganidan quvonadigan holda"},{ar:"وَيَسْخَرُونَ مِنْ جَهَالَتِهِمْ",uz:"va nodonliklarini masxara qiladigan holda"}],full_uz:"Chegaralardagi dushmanlarini esa ularning boshiga tushganidan quvonib, nodonliklarini masxara qiladigan holda qoldirib.",note:"شَمِتَ بِهِ — «uning baxtsizligidan quvonmoq». الثُّغُورُ — chegara mudofaa hududlari."},
{num:11,time:"00:01:13,680 --> 00:01:17,620",arabic:"قَاتَلَ اللَّهُ مَنْ أَشْعَلَهَا يَا مَوْلَايَ.",segs:[{ar:"قَاتَلَ اللَّهُ مَنْ أَشْعَلَهَا",uz:"Uni alangalatganni Alloh halok qilsin"},{ar:"يَا مَوْلَايَ",uz:"ey hazratim"}],full_uz:"Uni alangalatganni Alloh halok qilsin, hazratim.",note:"قَاتَلَ اللَّهُ ... — qarg‘ish ifodasi; bu yerda o‘tgan zamon voqeasi bildirilmayapti."},
{num:12,time:"00:01:17,620 --> 00:01:20,180",arabic:"نَحْنُ مَا ذَهَبْنَا إِلَيْهِمْ.",segs:null,full_uz:"Biz ularning oldiga bormadik.",note:null},
{num:13,time:"00:01:20,180 --> 00:01:23,420",arabic:"بَلْ هُمْ أَرَادُوهَا حَرْبًا نُقْتَلُ فِيهَا جَمِيعًا.",segs:[{ar:"بَلْ هُمْ أَرَادُوهَا حَرْبًا",uz:"Aksincha, ular buning urush bo‘lishini istashdi"},{ar:"نُقْتَلُ فِيهَا جَمِيعًا",uz:"unda hammamiz o‘ldiriladigan"}],full_uz:"Aksincha, ular buning hammamiz o‘ldiriladigan urush bo‘lishini istashdi.",note:"نُقْتَلُ — majhul nisbat: «biz o‘ldirilamiz»."},
{num:14,time:"00:01:23,420 --> 00:01:29,960",arabic:"لَيْسَ مُهِمًّا مَنْ أَشْعَلَهَا يَا أَبَا الْعَبَّاسِ.",segs:[{ar:"لَيْسَ مُهِمًّا مَنْ أَشْعَلَهَا",uz:"Uni kim alangalatgani muhim emas"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abul Abbos"}],full_uz:"Uni kim alangalatgani muhim emas, ey Abul Abbos.",note:null},
{num:15,time:"00:01:29,959 --> 00:01:34,780",arabic:"الْمُهِمُّ أَنَّهَا حَرْبٌ سَتَجُزُّ رِقَابَنَا جَمِيعًا.",segs:[{ar:"الْمُهِمُّ أَنَّهَا حَرْبٌ",uz:"Muhimi, bu urush"},{ar:"سَتَجُزُّ رِقَابَنَا جَمِيعًا",uz:"hammamizning bo‘ynimizni kesadigan"}],full_uz:"Muhimi, bu hammamizning bo‘ynimizni kesadigan urush.",note:"جَزَّ — يَجُزُّ: «kesmoq, qirqmoq»."},
{num:16,time:"00:01:34,780 --> 00:01:53,039",arabic:"كَيْفَ حَدَثَ ذَلِكَ؟",segs:null,full_uz:"Bu qanday sodir bo‘ldi?",note:null},
{num:17,time:"00:01:53,039 --> 00:01:54,479",arabic:"لَا أَدْرِي يَا مَوْلَايَ، لَا أَدْرِي.",segs:[{ar:"لَا أَدْرِي يَا مَوْلَايَ",uz:"Bilmayman, hazratim"},{ar:"لَا أَدْرِي",uz:"bilmayman"}],full_uz:"Bilmayman, hazratim, bilmayman.",note:null},
{num:18,time:"00:01:54,480 --> 00:02:00,719",arabic:"أَيُعْقَلُ أَنْ يَسْتَطِيعَ طَاهِرُ بْنُ الْحُسَيْنِ قَتْلَ ابْنِ مَاهَانَ وَتَمْزِيقَ جُنْدِهِ؟",segs:[{ar:"أَيُعْقَلُ أَنْ يَسْتَطِيعَ",uz:"Qodir bo‘lishi aqlga sig‘adimi"},{ar:"طَاهِرُ بْنُ الْحُسَيْنِ",uz:"Tohir ibn Husaynning"},{ar:"قَتْلَ ابْنِ مَاهَانَ",uz:"Ibn Mohonni o‘ldirishga"},{ar:"وَتَمْزِيقَ جُنْدِهِ",uz:"va uning qo‘shinini parchalashga?"}],full_uz:"Tohir ibn Husaynning Ibn Mohonni o‘ldirib, qo‘shinini parchalashga qodir bo‘lishi aqlga sig‘adimi?",note:null},
{num:19,time:"00:02:00,719 --> 00:02:02,560",arabic:"هَذَا مَا حَدَثَ يَا مَوْلَايَ، هَذَا مَا حَدَثَ.",segs:[{ar:"هَذَا مَا حَدَثَ يَا مَوْلَايَ",uz:"Shu sodir bo‘ldi, hazratim"},{ar:"هَذَا مَا حَدَثَ",uz:"shu sodir bo‘ldi"}],full_uz:"Shu sodir bo‘ldi, hazratim, shu sodir bo‘ldi.",note:null},
{num:20,time:"00:02:02,560 --> 00:02:10,180",arabic:"يَا لَلْخِذْلَانِ! أَرْبَعَةُ آلَافِ مَارِقٍ يَنْتَصِرُونَ عَلَى أَرْبَعِينَ أَلْفًا مِنْ خِيرَةِ جُنُودِنَا!",segs:[{ar:"يَا لَلْخِذْلَانِ",uz:"Qanday sharmandali mag‘lubiyat!"},{ar:"أَرْبَعَةُ آلَافِ مَارِقٍ",uz:"To‘rt ming itoatdan chiqqan kishi"},{ar:"يَنْتَصِرُونَ عَلَى أَرْبَعِينَ أَلْفًا",uz:"qirq ming kishi ustidan g‘alaba qozonyapti"},{ar:"مِنْ خِيرَةِ جُنُودِنَا",uz:"eng sara askarlarimizdan!"}],full_uz:"Qanday sharmandali mag‘lubiyat! To‘rt ming itoatdan chiqqan kishi qirq ming eng sara askarimiz ustidan g‘alaba qozonyapti!",note:"خِيرَةُ — «eng sarasi, eng yaxshilari»."},
{num:21,time:"00:02:10,180 --> 00:02:14,560",arabic:"أَيُّ خِذْلَانٍ هَذَا؟ أَيُّ خِذْلَانٍ هَذَا؟",segs:[{ar:"أَيُّ خِذْلَانٍ هَذَا",uz:"Bu qanday mag‘lubiyat?"},{ar:"أَيُّ خِذْلَانٍ هَذَا",uz:"Bu qanday mag‘lubiyat?"}],full_uz:"Bu qanday mag‘lubiyat? Bu qanday mag‘lubiyat?",note:null},
{num:22,time:"00:02:16,819 --> 00:02:21,360",arabic:"الْحَمْدُ لِلَّهِ الَّذِي هَزَمَ أَعْدَاءَكَ وَنَصَرَ جُنْدَكَ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"الْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"الَّذِي هَزَمَ أَعْدَاءَكَ",uz:"dushmanlaringizni mag‘lub etgan"},{ar:"وَنَصَرَ جُنْدَكَ",uz:"va qo‘shiningizga g‘alaba bergan"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Dushmanlaringizni mag‘lub etib, qo‘shiningizga g‘alaba bergan Allohga hamd bo‘lsin, ey mo‘minlar amiri.",note:null},
{num:23,time:"00:02:21,360 --> 00:02:26,780",arabic:"وَأَرَاكَ مَا تُحِبُّ مِنْ خَادِمِكَ وَقَائِدِ جُنْدِكَ طَاهِرِ بْنِ الْحُسَيْنِ.",segs:[{ar:"وَأَرَاكَ مَا تُحِبُّ",uz:"Va sizga yoqqan narsani ko‘rsatgan"},{ar:"مِنْ خَادِمِكَ وَقَائِدِ جُنْدِكَ",uz:"xizmatkoringiz va qo‘shiningiz qo‘mondonidan"},{ar:"طَاهِرِ بْنِ الْحُسَيْنِ",uz:"Tohir ibn Husayndan"}],full_uz:"Xizmatkoringiz va qo‘shiningiz qo‘mondoni Tohir ibn Husayndan sizga yoqqan ishlarni ko‘rsatgan Allohga.",note:"أَرَاكَ — «sizga ko‘rsatdi»; رَآكَ esa «sizni ko‘rdi»."},
{num:24,time:"00:02:26,780 --> 00:02:30,780",arabic:"بَارَكَ اللَّهُ فِيكُمْ يَا أَخْوَالَ أَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"بَارَكَ اللَّهُ فِيكُمْ",uz:"Alloh sizlarga baraka bersin"},{ar:"يَا أَخْوَالَ أَمِيرِ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amirining tog‘alari"}],full_uz:"Alloh sizlarga baraka bersin, ey mo‘minlar amirining tog‘alari.",note:"أَخْوَالٌ — خَالٌ («tog‘a») so‘zining ko‘pligi."},
{num:25,time:"00:02:30,780 --> 00:02:36,040",arabic:"لَوْلَا فَضْلُ اللَّهِ ثُمَّ وَفَاؤُكُمْ وَشَجَاعَتُكُمْ...",segs:[{ar:"لَوْلَا فَضْلُ اللَّهِ",uz:"Allohning fazli bo‘lmaganida"},{ar:"ثُمَّ وَفَاؤُكُمْ وَشَجَاعَتُكُمْ",uz:"so‘ng sizlarning sadoqat va jasoratingiz"}],full_uz:"Allohning fazli, so‘ng sizlarning sadoqat va jasoratingiz bo‘lmaganida...",note:null},
{num:26,time:"00:02:36,040 --> 00:02:38,700",arabic:"لَمَا كَانَ لِهَذَا النَّصْرِ أَنْ يَكُونَ.",segs:null,full_uz:"Bu g‘alaba yuz bermagan bo‘lardi.",note:"Oldingi banddagi لَوْلَا shartining javobi: «...bo‘lmaganida, bu yuz bermas edi»."},
{num:27,time:"00:02:38,700 --> 00:02:42,600",arabic:"إِنَّ مَقْتَلَ الْأَبْنَاوِيِّ بَعْدَ ابْنِ مَاهَانَ...",segs:[{ar:"إِنَّ مَقْتَلَ الْأَبْنَاوِيِّ",uz:"Abnoviyning o‘ldirilishi"},{ar:"بَعْدَ ابْنِ مَاهَانَ",uz:"Ibn Mohondan keyin"}],full_uz:"Ibn Mohondan keyin Abnoviyning o‘ldirilishi...",note:"مَقْتَلٌ bu yerda «o‘ldirilish, halok bo‘lish» ma’nosida."},
{num:28,time:"00:02:42,600 --> 00:02:46,000",arabic:"سَيُوهِنُ عَزْمَ أَهْلِ بَغْدَادَ إِنْ شَاءَ اللَّهُ.",segs:[{ar:"سَيُوهِنُ عَزْمَ أَهْلِ بَغْدَادَ",uz:"Bag‘dod ahlining qat’iyatini susaytiradi"},{ar:"إِنْ شَاءَ اللَّهُ",uz:"Alloh xohlasa"}],full_uz:"Alloh xohlasa, Bag‘dod ahlining qat’iyatini susaytiradi.",note:"أَوْهَنَ — يُوهِنُ: «zaiflashtirmoq, susaytirmoq»."},
{num:29,time:"00:02:46,000 --> 00:02:49,900",arabic:"لَعَلَّهُمْ يَعُودُونَ عَنْ غَيِّهِمْ وَطُغْيَانِهِمْ.",segs:[{ar:"لَعَلَّهُمْ يَعُودُونَ",uz:"Shoyad qaytsalar"},{ar:"عَنْ غَيِّهِمْ وَطُغْيَانِهِمْ",uz:"adashish va haddan oshishlaridan"}],full_uz:"Shoyad adashish va haddan oshishlaridan qaytsalar.",note:null},
{num:30,time:"00:02:49,900 --> 00:02:52,340",arabic:"إِنْ عَادُوا عُدْنَا يَا مَوْلَايَ.",segs:[{ar:"إِنْ عَادُوا عُدْنَا",uz:"Ular qaytsalar, biz ham qaytamiz"},{ar:"يَا مَوْلَايَ",uz:"ey hazratim"}],full_uz:"Ular qaytsalar, biz ham qaytamiz, hazratim.",note:null},
{num:31,time:"00:02:52,340 --> 00:02:54,939",arabic:"وَلَنْ يَعُودُوا إِلَّا لِهَزِيمَتِهِمْ.",segs:[{ar:"وَلَنْ يَعُودُوا إِلَّا",uz:"Ular faqat qaytadilar"},{ar:"لِهَزِيمَتِهِمْ",uz:"o‘z mag‘lubiyatlariga"}],full_uz:"Ular qaytsalar, faqat yana mag‘lub bo‘lish uchun qaytadilar.",note:null},
{num:32,time:"00:02:54,939 --> 00:02:58,060",arabic:"وَنَحْنُ إِلَى النَّصْرِ دَوْمًا إِنْ شَاءَ اللَّهُ.",segs:[{ar:"وَنَحْنُ إِلَى النَّصْرِ دَوْمًا",uz:"Biz esa doimo g‘alaba sari"},{ar:"إِنْ شَاءَ اللَّهُ",uz:"Alloh xohlasa"}],full_uz:"Biz esa, Alloh xohlasa, doimo g‘alaba sari boramiz.",note:null},
{num:33,time:"00:02:58,060 --> 00:03:08,200",arabic:"تُرَى كَمْ قُتِلَ مِنَ الْمُسْلِمِينَ فِي هَذِهِ الْحَرْبِ؟",segs:[{ar:"تُرَى كَمْ قُتِلَ مِنَ الْمُسْلِمِينَ",uz:"Qiziq, qancha musulmon o‘ldirildi ekan"},{ar:"فِي هَذِهِ الْحَرْبِ",uz:"bu urushda?"}],full_uz:"Qiziq, bu urushda qancha musulmon o‘ldirildi ekan?",note:null},
{num:34,time:"00:03:08,200 --> 00:03:12,040",arabic:"هَذَا مَا أَرَدْتَهُ يَا ابْنَ أَبِي.",segs:[{ar:"هَذَا مَا أَرَدْتَهُ",uz:"Istaganingiz shu edi"},{ar:"يَا ابْنَ أَبِي",uz:"ey otamning o‘g‘li"}],full_uz:"Istaganingiz shu edi, ey otamning o‘g‘li.",note:"يَا ابْنَ أَبِي — «ey otamning o‘g‘li»; birodarga murojaat."},
{num:35,time:"00:03:12,040 --> 00:03:17,640",arabic:"أَمَا كَانَ لَكَ فِي الْوَفَاءِ بِعَهْدِ أَبِيكَ مَنْدُوحَةٌ عَنْ كُلِّ ذَلِكَ؟",segs:[{ar:"أَمَا كَانَ لَكَ",uz:"Siz uchun yo‘q edimi"},{ar:"فِي الْوَفَاءِ بِعَهْدِ أَبِيكَ",uz:"otangizning ahdiga vafo qilishda"},{ar:"مَنْدُوحَةٌ عَنْ كُلِّ ذَلِكَ",uz:"bularning barchasidan qutulish yo‘li?"}],full_uz:"Otangizning ahdiga vafo qilishda siz uchun bularning barchasidan qutulish yo‘li yo‘qmidi?",note:"مَنْدُوحَةٌ عَنْ — bir narsadan qochish imkoniyati, uning o‘rnini bosadigan yo‘l."},
{num:36,time:"00:03:17,639 --> 00:03:24,519",arabic:"غَفَرَ اللَّهُ لَكَ يَا أَبَا مُوسَى، وَغَفَرَ لَنَا جَمِيعًا.",segs:[{ar:"غَفَرَ اللَّهُ لَكَ يَا أَبَا مُوسَى",uz:"Alloh sizni mag‘firat qilsin, ey Abu Muso"},{ar:"وَغَفَرَ لَنَا جَمِيعًا",uz:"va hammamizni mag‘firat qilsin"}],full_uz:"Alloh sizni mag‘firat qilsin, ey Abu Muso, hammamizni ham mag‘firat qilsin.",note:null},
{num:37,time:"00:03:24,519 --> 00:03:27,239",arabic:"لَا أَكْتُمُكَ سِرًّا يَا حَارِثُ.",segs:null,full_uz:"Sizdan sir yashirmayman, Horis.",note:"لَا أَكْتُمُكَ سِرًّا — «ochig‘ini aytaman» mazmunida ham ishlatiladi."},
{num:38,time:"00:03:27,239 --> 00:03:29,719",arabic:"إِنَّ الْأُمُورَ تَسِيرُ مِنْ سَيِّئٍ إِلَى أَسْوَأَ.",segs:[{ar:"إِنَّ الْأُمُورَ تَسِيرُ",uz:"Ishlar ketyapti"},{ar:"مِنْ سَيِّئٍ إِلَى أَسْوَأَ",uz:"yomondan yomonroqqa"}],full_uz:"Ishlar tobora yomonlashib boryapti.",note:"مِنْ سَيِّئٍ إِلَى أَسْوَأَ — «yomondan battarga»."},
{num:39,time:"00:03:29,719 --> 00:03:32,439",arabic:"لَقَدِ اسْتَوْلَى طَاهِرُ بْنُ الْحُسَيْنِ عَلَى الْبَصْرَةِ.",segs:[{ar:"لَقَدِ اسْتَوْلَى طَاهِرُ بْنُ الْحُسَيْنِ",uz:"Tohir ibn Husayn egallab oldi"},{ar:"عَلَى الْبَصْرَةِ",uz:"Basrani"}],full_uz:"Tohir ibn Husayn Basrani egallab oldi.",note:"اِسْتَوْلَى عَلَى — «...ni egallab olmoq»."},
{num:40,time:"00:03:32,439 --> 00:03:35,500",arabic:"بَعْدَ أَنْ أَحْكَمَ سَيْطَرَتَهُ عَلَى غَيْرِهَا مِنَ الْأَمْصَارِ.",segs:[{ar:"بَعْدَ أَنْ أَحْكَمَ سَيْطَرَتَهُ",uz:"Nazoratini mustahkamlaganidan keyin"},{ar:"عَلَى غَيْرِهَا مِنَ الْأَمْصَارِ",uz:"boshqa shaharlar ustidan"}],full_uz:"Boshqa shaharlar ustidan nazoratini mustahkamlaganidan keyin.",note:"أَحْكَمَ سَيْطَرَتَهُ — «nazoratini mustahkamlamoq»."},
{num:41,time:"00:03:35,500 --> 00:03:38,839",arabic:"وَأَخْشَى أَنْ نَرَاهُ بَعْدَ أَسَابِيعَ يُطَوِّقُ بَغْدَادَ.",segs:[{ar:"وَأَخْشَى أَنْ نَرَاهُ",uz:"Uni ko‘rishimizdan qo‘rqaman"},{ar:"بَعْدَ أَسَابِيعَ",uz:"bir necha haftadan keyin"},{ar:"يُطَوِّقُ بَغْدَادَ",uz:"Bag‘dodni qurshab olayotgan holda"}],full_uz:"Bir necha haftadan keyin uning Bag‘dodni qurshab olayotganini ko‘rishimizdan qo‘rqaman.",note:"طَوَّقَ — «qurshab olmoq, o‘rab olmoq»."},
{num:42,time:"00:03:38,839 --> 00:03:41,359",arabic:"كَيْفَ وَصَلَتِ الْأُمُورُ إِلَى هَذَا السُّوءِ؟",segs:[{ar:"كَيْفَ وَصَلَتِ الْأُمُورُ",uz:"Ishlar qanday yetib keldi"},{ar:"إِلَى هَذَا السُّوءِ",uz:"bu yomon ahvolga?"}],full_uz:"Ishlar qanday qilib bu yomon ahvolga yetib keldi?",note:null},
{num:43,time:"00:03:41,359 --> 00:03:43,239",arabic:"أَلَسْنَا أَكْثَرَ مِنْهُمْ عُدَّةً وَعَدَدًا؟",segs:[{ar:"أَلَسْنَا أَكْثَرَ مِنْهُمْ",uz:"Biz ulardan ko‘proq emasmizmi"},{ar:"عُدَّةً وَعَدَدًا",uz:"qurol-aslaha va son jihatidan?"}],full_uz:"Biz qurol-aslaha va son jihatidan ulardan ustun emasmizmi?",note:"عُدَّةٌ — jihoz va tayyorgarlik vositalari; عَدَدٌ — son."},
{num:44,time:"00:03:43,239 --> 00:03:47,239",arabic:"كَيْفَ يَتَسَاقَطُ قَادَةُ أَمِيرِ الْمُؤْمِنِينَ الْوَاحِدُ تِلْوَ الْآخَرِ؟",segs:[{ar:"كَيْفَ يَتَسَاقَطُ",uz:"Qanday qilib qulayapti"},{ar:"قَادَةُ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining qo‘mondonlari"},{ar:"الْوَاحِدُ تِلْوَ الْآخَرِ",uz:"birin-ketin?"}],full_uz:"Mo‘minlar amirining qo‘mondonlari qanday qilib birin-ketin qulayapti?",note:"الْوَاحِدُ تِلْوَ الْآخَرِ — «biri ketidan boshqasi, birin-ketin»."},
{num:45,time:"00:03:47,639 --> 00:03:49,079",arabic:"لَدَيْهِ الْوَلَاءُ الْمُطْلَقُ.",segs:null,full_uz:"Unga mutlaq sadoqat bor.",note:null},
{num:46,time:"00:03:49,079 --> 00:04:00,419",arabic:"إِنَّ جُنْدَهُ مُؤْمِنُونَ حَقَّ الْإِيمَانِ بِقَضِيَّتِهِمْ عَلَى الرَّغْمِ مِنْ فَسَادِهَا.",segs:[{ar:"إِنَّ جُنْدَهُ مُؤْمِنُونَ حَقَّ الْإِيمَانِ",uz:"Uning askarlari chin dildan ishonadilar"},{ar:"بِقَضِيَّتِهِمْ",uz:"o‘z maqsadlariga"},{ar:"عَلَى الرَّغْمِ مِنْ فَسَادِهَا",uz:"uning noto‘g‘riligiga qaramay"}],full_uz:"Uning askarlari maqsadlari noto‘g‘ri bo‘lsa ham, unga chin dildan ishonadilar.",note:"قَضِيَّةٌ bu yerda «kurash olib borilayotgan maqsad, da’vo» ma’nosida."},
{num:47,time:"00:04:00,419 --> 00:04:05,159",arabic:"إِنَّهُمْ يَعْلَمُونَ أَنَّ مَعْرَكَتَهُمْ مَعَنَا مَعْرَكَةُ حَيَاةٍ أَوْ مَوْتٍ.",segs:[{ar:"إِنَّهُمْ يَعْلَمُونَ",uz:"Ular biladilar"},{ar:"أَنَّ مَعْرَكَتَهُمْ مَعَنَا",uz:"biz bilan janglari"},{ar:"مَعْرَكَةُ حَيَاةٍ أَوْ مَوْتٍ",uz:"hayot yoki o‘lim jangi ekanini"}],full_uz:"Ular biz bilan janglari hayot yoki o‘lim jangi ekanini biladilar.",note:null},
{num:48,time:"00:04:05,159 --> 00:04:07,199",arabic:"أَمَّا جُنْدُنَا...",segs:null,full_uz:"Bizning askarlarimizga kelsak...",note:null},
{num:49,time:"00:04:07,199 --> 00:04:09,719",arabic:"تَعْسًا لِجُنْدِنَا!",segs:null,full_uz:"Askarlarimizning holiga voy!",note:"تَعْسًا لِـ — halokat va badbaxtlik tilash ifodasi."},
{num:50,time:"00:04:09,719 --> 00:04:16,539",arabic:"إِنَّهُمْ لَا يَهْتَمُّونَ إِلَّا بِالنُّقُودِ الَّتِي يُغْدِقُهَا عَلَيْهِمْ أَبُو مُوسَى الْأَمِينُ بِدُونِ حِسَابٍ.",segs:[{ar:"إِنَّهُمْ لَا يَهْتَمُّونَ إِلَّا بِالنُّقُودِ",uz:"Ular faqat pulga qiziqadilar"},{ar:"الَّتِي يُغْدِقُهَا عَلَيْهِمْ",uz:"ularning ustidan mo‘l-ko‘l yog‘diradigan"},{ar:"أَبُو مُوسَى الْأَمِينُ",uz:"Abu Muso Amin"},{ar:"بِدُونِ حِسَابٍ",uz:"hisobsiz"}],full_uz:"Ular faqat Abu Muso Amin ularga hisobsiz berayotgan pullarga qiziqadilar.",note:"أَغْدَقَ عَلَيْهِ — «unga mo‘l-ko‘l bermoq»."},
{num:51,time:"00:04:16,540 --> 00:04:17,960",arabic:"تَعْسًا لَهُمْ!",segs:null,full_uz:"Ularning holiga voy!",note:null},
{num:52,time:"00:04:17,960 --> 00:04:20,100",arabic:"أَلَا يَعْلَمُونَ أَنَّ هَزِيمَتَنَا...",segs:[{ar:"أَلَا يَعْلَمُونَ",uz:"Bilmaydilarmi"},{ar:"أَنَّ هَزِيمَتَنَا",uz:"bizning mag‘lubiyatimiz"}],full_uz:"Bizning mag‘lubiyatimiz ... ekanini bilmaydilarmi?",note:null},
{num:53,time:"00:04:20,100 --> 00:04:23,760",arabic:"سَتَجْعَلُ الْمَأْمُونَ وَمَنْ مَعَهُ أَسْيَادًا عَلَيْنَا؟",segs:[{ar:"سَتَجْعَلُ الْمَأْمُونَ وَمَنْ مَعَهُ",uz:"Ma’mun va uning yonidagilarni qiladi"},{ar:"أَسْيَادًا عَلَيْنَا",uz:"ustimizdan xo‘jayinlar?"}],full_uz:"Ma’mun va uning yonidagilarni ustimizdan xo‘jayin qilib qo‘yishini?",note:null},
{num:54,time:"00:04:25,439 --> 00:04:26,980",arabic:"هُمْ عُبَّادٌ لِلْمَالِ.",segs:null,full_uz:"Ular pulga sig‘inuvchilardir.",note:"عُبَّادٌ — عَابِدٌ ning ko‘pligi; bu yerda pulga haddan tashqari berilganlik ifodalangan."},
{num:55,time:"00:04:26,980 --> 00:04:30,800",arabic:"مَنْ يُعْطِي أَكْثَرَ يَشْتَرِي الْوَلَاءَ أَكْثَرَ.",segs:[{ar:"مَنْ يُعْطِي أَكْثَرَ",uz:"Kim ko‘proq bersa"},{ar:"يَشْتَرِي الْوَلَاءَ أَكْثَرَ",uz:"sadoqatni ko‘proq sotib oladi"}],full_uz:"Kim ko‘proq bersa, sadoqatni ham ko‘proq sotib oladi.",note:null},
{num:56,time:"00:04:30,800 --> 00:04:34,939",arabic:"وَأَنْتَ لَمْ تَرَ الْخِذْلَانَ بَعْدُ.",segs:null,full_uz:"Siz hali haqiqiy mag‘lubiyatni ko‘rmadingiz.",note:"لَمْ ... بَعْدُ — «hali ...madi»."},
{num:57,time:"00:04:34,939 --> 00:04:40,600",arabic:"غَدًا عِنْدَمَا يَتَمَكَّنُ الْمَأْمُونُ وَمَنْ مَعَهُ مِنْ رِقَابِنَا...",segs:[{ar:"غَدًا عِنْدَمَا يَتَمَكَّنُ",uz:"Ertaga qo‘lga olganida"},{ar:"الْمَأْمُونُ وَمَنْ مَعَهُ",uz:"Ma’mun va uning yonidagilar"},{ar:"مِنْ رِقَابِنَا",uz:"bizning bo‘ynimizni"}],full_uz:"Ertaga Ma’mun va uning yonidagilar bo‘ynimizni qo‘lga olganida...",note:"تَمَكَّنَ مِنْ رِقَابِهِمْ — ularni to‘liq o‘z hukmiga olish, hayotini o‘z qo‘liga olish timsoli."},
{num:58,time:"00:04:40,600 --> 00:04:44,020",arabic:"سَتَعْرِفُ مَا هُوَ الْخِذْلَانُ حَقًّا.",segs:[{ar:"سَتَعْرِفُ",uz:"Bilib olasiz"},{ar:"مَا هُوَ الْخِذْلَانُ حَقًّا",uz:"mag‘lubiyat aslida nima ekanini"}],full_uz:"Mag‘lubiyat aslida nima ekanini bilib olasiz.",note:null},
{num:59,time:"00:04:46,540 --> 00:04:52,700",arabic:"أَيُّهَا الْإِخْوَةُ، يَجِبُ أَنْ نُحَرِّضَ النَّاسَ فِي بَغْدَادَ عَلَى هَذَا الظَّالِمِ.",segs:[{ar:"أَيُّهَا الْإِخْوَةُ",uz:"Ey birodarlar"},{ar:"يَجِبُ أَنْ نُحَرِّضَ النَّاسَ",uz:"odamlarni undashimiz kerak"},{ar:"فِي بَغْدَادَ",uz:"Bag‘dodda"},{ar:"عَلَى هَذَا الظَّالِمِ",uz:"bu zolimga qarshi"}],full_uz:"Ey birodarlar, Bag‘doddagi odamlarni bu zolimga qarshi undashimiz kerak.",note:"حَرَّضَ فُلَانًا عَلَى فُلَانٍ — birovni boshqasiga qarshi qayramoq."},
{num:60,time:"00:04:52,700 --> 00:04:57,879",arabic:"يَجِبُ تَأْلِيبُهُمْ عَلَى الْأَمِينِ حَتَّى نُعَجِّلَ بِالْخَلَاصِ مِنْهُ.",segs:[{ar:"يَجِبُ تَأْلِيبُهُمْ عَلَى الْأَمِينِ",uz:"Ularni Aminga qarshi gijgijlash kerak"},{ar:"حَتَّى نُعَجِّلَ بِالْخَلَاصِ مِنْهُ",uz:"undan qutulishni tezlashtirishimiz uchun"}],full_uz:"Amindan qutulishni tezlashtirish uchun ularni unga qarshi gijgijlash kerak.",note:"تَأْلِيبٌ — odamlarni birovga qarshi birlashtirish, qayrash."},
{num:61,time:"00:04:57,879 --> 00:05:05,780",arabic:"وَلَكِنْ كَيْفَ؟ وَهُوَ يَشْتَرِي الْمُؤَيِّدِينَ بِالنُّقُودِ وَيَصْرِفُ أَمْوَالًا طَائِلَةً لِتَجْنِيدِ النَّاسِ كَيْ تُقَاتِلَ عَنْهُ أَخَاهُ الْمَأْمُونَ.",segs:[{ar:"وَلَكِنْ كَيْفَ",uz:"Ammo qanday?"},{ar:"وَهُوَ يَشْتَرِي الْمُؤَيِّدِينَ بِالنُّقُودِ",uz:"U tarafdorlarni pulga sotib olyapti"},{ar:"وَيَصْرِفُ أَمْوَالًا طَائِلَةً",uz:"va juda katta mablag‘ sarflayapti"},{ar:"لِتَجْنِيدِ النَّاسِ",uz:"odamlarni askarlikka olish uchun"},{ar:"كَيْ تُقَاتِلَ عَنْهُ",uz:"uning nomidan jang qilishlari uchun"},{ar:"أَخَاهُ الْمَأْمُونَ",uz:"birodari Ma’munga qarshi"}],full_uz:"Ammo qanday? U tarafdorlarni pulga sotib olib, uning nomidan birodari Ma’munga qarshi jang qilishlari uchun odamlarni askarlikka olishga juda katta mablag‘ sarflayapti.",note:"أَمْوَالٌ طَائِلَةٌ — juda katta mablag‘lar. قَاتَلَ عَنْهُ — uning tarafidan jang qildi."},
{num:62,time:"00:05:05,780 --> 00:05:09,780",arabic:"أَلَيْسَتْ تِلْكَ أَمْوَالَ الْمُسْلِمِينَ يُبَعْثِرُهَا عَدُوُّ اللَّهِ ذَاكَ؟",segs:[{ar:"أَلَيْسَتْ تِلْكَ أَمْوَالَ الْمُسْلِمِينَ",uz:"Bular musulmonlarning mablag‘lari emasmi"},{ar:"يُبَعْثِرُهَا عَدُوُّ اللَّهِ ذَاكَ",uz:"o‘sha Alloh dushmani sovurayotgan?"}],full_uz:"O‘sha Alloh dushmani sovurayotgan mablag‘lar musulmonlarning mablag‘lari emasmi?",note:"بَعْثَرَ — sochib yubormoq; pul haqida «sovurmoq»."},
{num:63,time:"00:05:10,439 --> 00:05:12,879",arabic:"يَقْتُلُ الْمُسْلِمِينَ بِأَمْوَالِ الْمُسْلِمِينَ.",segs:[{ar:"يَقْتُلُ الْمُسْلِمِينَ",uz:"Musulmonlarni o‘ldiryapti"},{ar:"بِأَمْوَالِ الْمُسْلِمِينَ",uz:"musulmonlarning pullari bilan"}],full_uz:"Musulmonlarni musulmonlarning pullari bilan o‘ldiryapti.",note:null},
{num:64,time:"00:05:12,879 --> 00:05:16,639",arabic:"إِنَّ كُلَّ سِلَاحٍ بِيَدِ الْجُنْدِ هُوَ مِنْ مَالِ الْمُسْلِمِينَ.",segs:[{ar:"إِنَّ كُلَّ سِلَاحٍ بِيَدِ الْجُنْدِ",uz:"Askarlar qo‘lidagi har bir qurol"},{ar:"هُوَ مِنْ مَالِ الْمُسْلِمِينَ",uz:"musulmonlarning molidan"}],full_uz:"Askarlar qo‘lidagi har bir qurol musulmonlarning molidan olingan.",note:null},
{num:65,time:"00:05:16,639 --> 00:05:20,120",arabic:"فَكَيْفَ يَقْتُلُ الْمُسْلِمِينَ بِأَمْوَالِهِمْ؟",segs:[{ar:"فَكَيْفَ يَقْتُلُ الْمُسْلِمِينَ",uz:"Qanday qilib musulmonlarni o‘ldiradi"},{ar:"بِأَمْوَالِهِمْ",uz:"ularning o‘z pullari bilan?"}],full_uz:"Qanday qilib musulmonlarni o‘z pullari bilan o‘ldiradi?",note:null},
{num:66,time:"00:05:20,120 --> 00:05:23,379",arabic:"هَذَا الْكَلَامُ يَجِبُ أَنْ يَصِلَ إِلَى النَّاسِ.",segs:[{ar:"هَذَا الْكَلَامُ",uz:"Bu gap"},{ar:"يَجِبُ أَنْ يَصِلَ إِلَى النَّاسِ",uz:"odamlarga yetib borishi kerak"}],full_uz:"Bu gap odamlarga yetib borishi kerak.",note:null},
{num:67,time:"00:05:23,379 --> 00:05:25,219",arabic:"أَيُّهَا الْإِخْوَةُ.",segs:null,full_uz:"Ey birodarlar.",note:null},
{num:68,time:"00:05:25,219 --> 00:05:27,420",arabic:"يَجِبُ أَنْ يَسْقُطَ مِنْ قُلُوبِ النَّاسِ.",segs:[{ar:"يَجِبُ أَنْ يَسْقُطَ",uz:"U tushishi kerak"},{ar:"مِنْ قُلُوبِ النَّاسِ",uz:"odamlarning qalbidan"}],full_uz:"U odamlarning qalbidan tushishi kerak.",note:"سَقَطَ مِنْ قَلْبِهِ — uning hurmati yoki muhabbatidan ayrilmoq."},
{num:69,time:"00:05:27,420 --> 00:05:30,719",arabic:"قَبْلَ أَنْ يَسْقُطَ بِسُيُوفِ أَهْلِ خُرَاسَانَ.",segs:[{ar:"قَبْلَ أَنْ يَسْقُطَ",uz:"Qulashidan oldin"},{ar:"بِسُيُوفِ أَهْلِ خُرَاسَانَ",uz:"Xuroson ahlining qilichlari bilan"}],full_uz:"Xuroson ahlining qilichlari bilan qulashidan oldin.",note:null},
{num:70,time:"00:05:30,719 --> 00:05:31,620",arabic:"أَفَهِمْتُمْ؟",segs:null,full_uz:"Tushundingizmi?",note:null},
{num:71,time:"00:05:32,120 --> 00:05:37,480",arabic:"أَعْلَمُ أَنَّ أَمِيرَ الْمُؤْمِنِينَ لَدَيْهِ مَا يَشْغَلُهُ.",segs:[{ar:"أَعْلَمُ أَنَّ أَمِيرَ الْمُؤْمِنِينَ",uz:"Bilaman, mo‘minlar amirining"},{ar:"لَدَيْهِ مَا يَشْغَلُهُ",uz:"uni band qiladigan ishlari bor"}],full_uz:"Bilaman, mo‘minlar amirining uni band qiladigan ishlari bor.",note:null},
{num:72,time:"00:05:37,480 --> 00:05:44,240",arabic:"وَلَكِنْ رَأَيْتُ مِنْ وَاجِبِي أَنْ أَسْتَأْذِنَكَ قَبْلَ أَنْ أَخْرُجَ إِلَى مَكَّةَ الْمُكَرَّمَةِ.",segs:[{ar:"وَلَكِنْ رَأَيْتُ مِنْ وَاجِبِي",uz:"Ammo o‘z burchim deb bildim"},{ar:"أَنْ أَسْتَأْذِنَكَ",uz:"sizdan izn so‘rashni"},{ar:"قَبْلَ أَنْ أَخْرُجَ",uz:"yo‘lga chiqishimdan oldin"},{ar:"إِلَى مَكَّةَ الْمُكَرَّمَةِ",uz:"Makkai Mukarramaga"}],full_uz:"Ammo Makkai Mukarramaga yo‘lga chiqishimdan oldin sizdan izn so‘rashni o‘z burchim deb bildim.",note:"اِسْتَأْذَنَ — «ruxsat, izn so‘ramoq»."},
{num:73,time:"00:05:44,240 --> 00:05:48,160",arabic:"لَوْ أَمْتَعْتَنَا بِبَقَائِكَ يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"لَوْ أَمْتَعْتَنَا بِبَقَائِكَ",uz:"Qolishingiz bilan bizni xursand qilsangiz edi"},{ar:"يَا أَبَا عَبْدِ اللَّهِ",uz:"ey Abu Abdulloh"}],full_uz:"Qolishingiz bilan bizni xursand qilsangiz edi, ey Abu Abdulloh.",note:"لَوْ bu yerda istak yoki muloyim taklifni bildiradi."},
{num:74,time:"00:05:48,160 --> 00:05:51,580",arabic:"فَوَاللَّهِ رُؤْيَتُكَ تَشْرَحُ الصَّدْرَ.",segs:[{ar:"فَوَاللَّهِ",uz:"Allohga qasam"},{ar:"رُؤْيَتُكَ تَشْرَحُ الصَّدْرَ",uz:"sizni ko‘rish ko‘ngilni ochadi"}],full_uz:"Allohga qasam, sizni ko‘rish ko‘ngilni ochadi.",note:"شَرَحَ الصَّدْرَ — «ko‘ngilni ochmoq, taskin bermoq»."},
{num:75,time:"00:05:51,580 --> 00:05:54,480",arabic:"رَغْمَ كَثْرَةِ الْهُمُومِ وَالْمَوَاجِعِ.",segs:[{ar:"رَغْمَ كَثْرَةِ",uz:"Ko‘pligiga qaramay"},{ar:"الْهُمُومِ وَالْمَوَاجِعِ",uz:"tashvishlar va dardlarning"}],full_uz:"Tashvishlar va dardlarning ko‘pligiga qaramay.",note:null},
{num:76,time:"00:05:56,200 --> 00:05:58,480",arabic:"لَا أَشْغَلَ اللَّهُ بَالَكَ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"لَا أَشْغَلَ اللَّهُ بَالَكَ",uz:"Alloh ko‘nglingizni tashvishga solmasin"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Alloh ko‘nglingizni tashvishga solmasin, ey mo‘minlar amiri.",note:null},
{num:77,time:"00:05:59,259 --> 00:06:04,840",arabic:"إِنَّ لِلْأُمُورِ أَوَاخِرَ أَبَدًا مَا دَامَ لَهَا أَوَائِلُ.",segs:[{ar:"إِنَّ لِلْأُمُورِ أَوَاخِرَ أَبَدًا",uz:"Ishlarning doimo oxiri bor"},{ar:"مَا دَامَ لَهَا أَوَائِلُ",uz:"ularning boshi bor ekan"}],full_uz:"Ishlarning boshi bor ekan, albatta oxiri ham bor.",note:"أَوَائِلُ — boshlanishlar; أَوَاخِرُ — oxirlar. مَا دَامَ — «...ekan, ...modomiki»."},
{num:78,time:"00:06:04,839 --> 00:06:13,839",arabic:"وَإِنْ أَذِنْتَ لِي قُلْتُ شَيْئًا يَجْدُرُ بِمِثْلِي أَنْ يَقُولَهُ فِي سَاعَةٍ مِثْلِ هَذِهِ.",segs:[{ar:"وَإِنْ أَذِنْتَ لِي",uz:"Agar menga ruxsat bersangiz"},{ar:"قُلْتُ شَيْئًا",uz:"bir gap aytaman"},{ar:"يَجْدُرُ بِمِثْلِي أَنْ يَقُولَهُ",uz:"menga o‘xshagan kishi aytishi munosib bo‘lgan"},{ar:"فِي سَاعَةٍ مِثْلِ هَذِهِ",uz:"bunday bir paytda"}],full_uz:"Agar ruxsat bersangiz, bunday paytda menga o‘xshagan kishi aytishi munosib bo‘lgan bir gapni aytaman.",note:"يَجْدُرُ بِهِ أَنْ — «uning ...qilishi munosib, lozim»."},
{num:79,time:"00:06:13,839 --> 00:06:17,079",arabic:"قُلْ يَا أَبَا عَبْدِ اللَّهِ.",segs:null,full_uz:"Ayting, ey Abu Abdulloh.",note:null},
{num:80,time:"00:06:17,079 --> 00:06:20,459",arabic:"إِنِّي فِي شَغَفٍ لِسَمَاعِ كَلَامِكَ.",segs:[{ar:"إِنِّي فِي شَغَفٍ",uz:"Men juda ishtiyoqmandman"},{ar:"لِسَمَاعِ كَلَامِكَ",uz:"so‘zlaringizni eshitishga"}],full_uz:"So‘zlaringizni eshitishga juda ishtiyoqmandman.",note:"شَغَفٌ — kuchli qiziqish, ishtiyoq."},
{num:81,time:"00:06:20,459 --> 00:06:26,579",arabic:"حَقْنُ دَمِ الْمُسْلِمِينَ أَوْلَى مِنْ سَفْكِهِ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"حَقْنُ دَمِ الْمُسْلِمِينَ",uz:"Musulmonlarning qonini saqlash"},{ar:"أَوْلَى مِنْ سَفْكِهِ",uz:"uni to‘kishdan afzalroq"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Musulmonlarning qonini saqlash uni to‘kishdan afzalroq, ey mo‘minlar amiri.",note:"حَقْنُ الدَّمِ — qon to‘kilishining oldini olish; سَفْكُهُ — uni to‘kish."},
{num:82,time:"00:06:26,579 --> 00:06:30,139",arabic:"وَفِي الْحِوَارِ مَنْدُوحَةٌ بَيْنَ النَّاسِ.",segs:[{ar:"وَفِي الْحِوَارِ مَنْدُوحَةٌ",uz:"Muloqotda chiqish yo‘li bor"},{ar:"بَيْنَ النَّاسِ",uz:"odamlar o‘rtasida"}],full_uz:"Odamlar o‘rtasidagi muloqotda chiqish yo‘li bor.",note:null},
{num:83,time:"00:06:30,139 --> 00:06:33,219",arabic:"فَكَيْفَ بِهِ بَيْنَ الْإِخْوَةِ مِنَ الْمُؤْمِنِينَ؟",segs:[{ar:"فَكَيْفَ بِهِ",uz:"Unda uning o‘rni qanday bo‘ladi"},{ar:"بَيْنَ الْإِخْوَةِ مِنَ الْمُؤْمِنِينَ",uz:"mo‘min birodarlar o‘rtasida?"}],full_uz:"Mo‘min birodarlar o‘rtasida esa muloqotning o‘rni yanada katta emasmi?",note:"فَكَيْفَ بِهِ bu yerda oldingi fikrning keyingi holatga yanada kuchliroq tegishli ekanini bildiradi."},
{num:84,time:"00:06:33,220 --> 00:06:41,140",arabic:"أَمَّا بَعْدُ، فَأَنْتَ أَمِيرُ الْمُؤْمِنِينَ وَنَجْلُ هَارُونَ الرَّشِيدِ رَحِمَهُ اللَّهُ.",segs:[{ar:"أَمَّا بَعْدُ",uz:"Endi gapning davomiga kelsak"},{ar:"فَأَنْتَ أَمِيرُ الْمُؤْمِنِينَ",uz:"siz mo‘minlar amirisiz"},{ar:"وَنَجْلُ هَارُونَ الرَّشِيدِ",uz:"va Horun Rashidning o‘g‘lisiz"},{ar:"رَحِمَهُ اللَّهُ",uz:"Alloh uni rahmat qilsin"}],full_uz:"Endi gapning davomiga kelsak, siz mo‘minlar amiri va Horun Rashidning o‘g‘lisiz. Alloh uni rahmat qilsin.",note:"نَجْلٌ — o‘g‘il, farzand."},
{num:85,time:"00:06:41,140 --> 00:06:45,980",arabic:"وَخَصْمُكَ كَمَا تَرَاهُ الْأَمِيرُ الْمَأْمُونُ.",segs:[{ar:"وَخَصْمُكَ كَمَا تَرَاهُ",uz:"Siz raqib deb bilayotgan kishi esa"},{ar:"الْأَمِيرُ الْمَأْمُونُ",uz:"amir Ma’mundir"}],full_uz:"Siz raqib deb bilayotgan kishi esa amir Ma’mundir.",note:null},
{num:86,time:"00:06:45,980 --> 00:06:53,220",arabic:"فَهَلَّا غَلَّبْتَ يَا مَوْلَايَ حُرْمَةَ الدَّمِ وَصِلَةَ الرَّحِمِ عَلَى قَعْقَعَةِ السُّيُوفِ؟",segs:[{ar:"فَهَلَّا غَلَّبْتَ يَا مَوْلَايَ",uz:"Ustun qo‘ysangiz bo‘lmasmidi, hazratim"},{ar:"حُرْمَةَ الدَّمِ",uz:"qonning daxlsizligini"},{ar:"وَصِلَةَ الرَّحِمِ",uz:"va qarindoshlik rishtalarini"},{ar:"عَلَى قَعْقَعَةِ السُّيُوفِ",uz:"qilichlarning jarangidan?"}],full_uz:"Hazratim, qonning daxlsizligi va qarindoshlik rishtalarini qilichlar jarangidan ustun qo‘ysangiz bo‘lmasmidi?",note:"هَلَّا — taklif yoki undash vositasi. قَعْقَعَةُ السُّيُوفِ — qilichlarning jaranglashi."},
{num:87,time:"00:06:59,220 --> 00:07:02,160",arabic:"لَقَدْ سَبَقَ السَّيْفُ الْعَذَلَ يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"لَقَدْ سَبَقَ السَّيْفُ الْعَذَلَ",uz:"Qilich malomatdan oldin ishga tushib bo‘ldi"},{ar:"يَا أَبَا عَبْدِ اللَّهِ",uz:"ey Abu Abdulloh"}],full_uz:"Qilich malomatdan oldin ishga tushib bo‘ldi, ey Abu Abdulloh.",note:"سَبَقَ السَّيْفُ الْعَذَلَ — ish amalga oshib bo‘lganini, endi tanbeh yoki nasihat kech ekanini bildiradigan maqol."},
{num:88,time:"00:07:02,160 --> 00:07:05,720",arabic:"مَا دَامَ فِي الْقَلْبِ نِيَّةٌ...",segs:null,full_uz:"Qalbda niyat bor ekan...",note:null},
{num:89,time:"00:07:05,720 --> 00:07:09,760",arabic:"وَفِي الْعَقْلِ رَأْيٌ وَفِي النَّفْسِ عَزْمٌ.",segs:[{ar:"وَفِي الْعَقْلِ رَأْيٌ",uz:"aqlimizda fikr"},{ar:"وَفِي النَّفْسِ عَزْمٌ",uz:"va ichimizda qat’iyat bor ekan"}],full_uz:"Aqlda fikr, ichimizda qat’iyat bor ekan...",note:null},
{num:90,time:"00:07:09,760 --> 00:07:11,420",arabic:"وَفِي الْوَقْتِ مُتَّسَعٌ.",segs:null,full_uz:"Va hali vaqt imkon berar ekan...",note:"مُتَّسَعٌ — kenglik, yetarli imkon; vaqt haqida «hali fursat borligi»."},
{num:91,time:"00:07:11,420 --> 00:07:15,840",arabic:"فَكُلُّ شَيْءٍ يُمْكِنُ تَدَارُكُهُ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"فَكُلُّ شَيْءٍ يُمْكِنُ تَدَارُكُهُ",uz:"har bir narsani o‘nglash mumkin"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Har bir narsani o‘nglash mumkin, ey mo‘minlar amiri.",note:"تَدَارَكَ الْأَمْرَ — kech bo‘lmasidan ishni o‘nglamoq, zararining oldini olmoq."},
{num:92,time:"00:07:15,840 --> 00:07:17,280",arabic:"إِذَا انْطَلَقَ السَّهْمُ...",segs:null,full_uz:"O‘q otilgach...",note:null},
{num:93,time:"00:07:17,280 --> 00:07:20,620",arabic:"فَلَا رَدَّ لَهُ يَا ابْنَ إِدْرِيسَ.",segs:[{ar:"فَلَا رَدَّ لَهُ",uz:"uni qaytarib bo‘lmaydi"},{ar:"يَا ابْنَ إِدْرِيسَ",uz:"ey Ibn Idris"}],full_uz:"Uni qaytarib bo‘lmaydi, ey Ibn Idris.",note:null},
{num:94,time:"00:07:20,620 --> 00:07:26,680",arabic:"وَلَكِنَّ الْحَرْبَ خَرَجَتْ مِنْ يَدِ أَخِي الْمَأْمُونِ.",segs:[{ar:"وَلَكِنَّ الْحَرْبَ خَرَجَتْ",uz:"Ammo urush chiqib ketdi"},{ar:"مِنْ يَدِ أَخِي الْمَأْمُونِ",uz:"birodarim Ma’munning qo‘lidan"}],full_uz:"Ammo urush birodarim Ma’munning qo‘lidan chiqib ketdi.",note:"خَرَجَ الْأَمْرُ مِنْ يَدِهِ — ish uning nazoratidan chiqdi."},
{num:95,time:"00:07:26,680 --> 00:07:31,680",arabic:"إِلَى يَدِ قَوْمٍ جُفَاةٍ غِلَاظٍ حَاقِدِينَ.",segs:[{ar:"إِلَى يَدِ قَوْمٍ",uz:"Bir guruh kishilarning qo‘liga"},{ar:"جُفَاةٍ غِلَاظٍ حَاقِدِينَ",uz:"qo‘pol, toshbag‘ir va kinli"}],full_uz:"Qo‘pol, toshbag‘ir va kinli kishilarning qo‘liga o‘tdi.",note:"جُفَاةٌ — qo‘pol kishilar; غِلَاظٌ — qattiqqo‘l, toshbag‘ir kishilar."},
{num:96,time:"00:07:31,680 --> 00:07:36,860",arabic:"لَنْ يَقْبَلُوا الصُّلْحَ حَتَّى لَوْ قَبِلَ أَخِي الْمَأْمُونُ.",segs:[{ar:"لَنْ يَقْبَلُوا الصُّلْحَ",uz:"Ular sulhni qabul qilmaydilar"},{ar:"حَتَّى لَوْ قَبِلَ أَخِي الْمَأْمُونُ",uz:"hatto birodarim Ma’mun qabul qilsa ham"}],full_uz:"Hatto birodarim Ma’mun qabul qilsa ham, ular sulhni qabul qilmaydilar.",note:"حَتَّى لَوْ — «hatto ...bo‘lsa ham»."},
{num:97,time:"00:07:36,860 --> 00:07:43,680",arabic:"هَذِهِ الْحَرْبُ أَصْبَحَتْ أَكْبَرَ مِنَّا جَمِيعًا.",segs:[{ar:"هَذِهِ الْحَرْبُ أَصْبَحَتْ",uz:"Bu urush bo‘lib qoldi"},{ar:"أَكْبَرَ مِنَّا جَمِيعًا",uz:"hammamizdan ham kattaroq"}],full_uz:"Bu urush hammamizdan ham kattaroq bo‘lib qoldi.",note:null},
{num:98,time:"00:07:43,680 --> 00:07:50,000",arabic:"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ.",segs:[{ar:"إِنَّا لِلَّهِ",uz:"Albatta, biz Allohnikimiz"},{ar:"وَإِنَّا إِلَيْهِ رَاجِعُونَ",uz:"va albatta, Unga qaytuvchimiz"}],full_uz:"Albatta, biz Allohnikimiz va albatta, Unga qaytuvchimiz.",note:null},
{num:99,time:"00:08:01,680 --> 00:08:21,060",arabic:"إِنَّ هَذِهِ الْحَرْبَ أَيُّهَا الْإِخْوَةُ وَبَالٌ عَلَى الْإِسْلَامِ.",segs:[{ar:"إِنَّ هَذِهِ الْحَرْبَ",uz:"Darhaqiqat, bu urush"},{ar:"أَيُّهَا الْإِخْوَةُ",uz:"ey birodarlar"},{ar:"وَبَالٌ عَلَى الْإِسْلَامِ",uz:"Islom uchun falokatdir"}],full_uz:"Ey birodarlar, bu urush Islom uchun falokatdir.",note:"وَبَالٌ — og‘ir zarar, yomon oqibat, falokat."},
{num:100,time:"00:08:21,060 --> 00:08:23,600",arabic:"لَمْ تَقُمْ لِإِعْلَاءِ كَلِمَةِ اللَّهِ.",segs:[{ar:"لَمْ تَقُمْ",uz:"U boshlanmadi"},{ar:"لِإِعْلَاءِ كَلِمَةِ اللَّهِ",uz:"Allohning kalimasini yuksaltirish uchun"}],full_uz:"U Allohning kalimasini yuksaltirish uchun boshlanmadi.",note:"قَامَتِ الْحَرْبُ — «urush boshlandi»."},
{num:101,time:"00:08:23,600 --> 00:08:26,379",arabic:"بَلْ قَامَتْ مِنْ أَجْلِ مَطَامِعَ فِي الْحُكْمِ.",segs:[{ar:"بَلْ قَامَتْ مِنْ أَجْلِ",uz:"Aksincha, u tufayli boshlandi"},{ar:"مَطَامِعَ فِي الْحُكْمِ",uz:"hokimiyatga bo‘lgan ochko‘z intilishlar"}],full_uz:"Aksincha, u hokimiyatga bo‘lgan ochko‘z intilishlar tufayli boshlandi.",note:"مَطَامِعُ — طَمَعٌ bilan bog‘liq bo‘lib, manfaatparast istak va intilishlarni bildiradi."},
{num:102,time:"00:08:26,379 --> 00:08:29,639",arabic:"وَرَغْبَةٍ فَاسِدَةٍ فِي الِاسْتِئْثَارِ بِالسُّلْطَانِ.",segs:[{ar:"وَرَغْبَةٍ فَاسِدَةٍ",uz:"Va buzuq istak tufayli"},{ar:"فِي الِاسْتِئْثَارِ بِالسُّلْطَانِ",uz:"hokimiyatni yolg‘iz egallab olishga"}],full_uz:"Va hokimiyatni yolg‘iz egallab olishga bo‘lgan buzuq istak tufayli.",note:"اِسْتَأْثَرَ بِالشَّيْءِ — bir narsani boshqalar bilan bo‘lishmay, o‘ziga xos qilib olmoq."},
{num:103,time:"00:08:29,639 --> 00:08:31,899",arabic:"وَلَكِنَّ الْمَأْمُونَ هُوَ مَنْ بَدَأَ بِالشَّرِّ.",segs:[{ar:"وَلَكِنَّ الْمَأْمُونَ",uz:"Ammo Ma’mun"},{ar:"هُوَ مَنْ بَدَأَ بِالشَّرِّ",uz:"yomonlikni boshlagan kishidir"}],full_uz:"Ammo yomonlikni boshlagan Ma’mundir.",note:null},
{num:104,time:"00:08:31,899 --> 00:08:34,019",arabic:"أَيًّا يَكُنْ يَا أَخِي.",segs:null,full_uz:"Kim bo‘lishidan qat’i nazar, birodarim.",note:"أَيًّا يَكُنْ — «kim yoki nima bo‘lishidan qat’i nazar»."},
{num:105,time:"00:08:34,019 --> 00:08:36,139",arabic:"إِنَّ مَنْ يُشَارِكُ فِي هَذِهِ الْحَرْبِ آثِمٌ.",segs:[{ar:"إِنَّ مَنْ يُشَارِكُ فِي هَذِهِ الْحَرْبِ",uz:"Bu urushda qatnashadigan kishi"},{ar:"آثِمٌ",uz:"gunohkordir"}],full_uz:"Bu urushda qatnashadigan kishi gunohkordir.",note:"آثِمٌ — gunoh qiluvchi, gunohkor."},
{num:106,time:"00:08:36,139 --> 00:08:39,100",arabic:"وَالْعَاقِلُ هُوَ مَنْ لَزِمَ دَارَهُ.",segs:[{ar:"وَالْعَاقِلُ هُوَ مَنْ",uz:"Oqil kishi shuki"},{ar:"لَزِمَ دَارَهُ",uz:"uyidan chiqmaydi"}],full_uz:"Oqil kishi uyidan chiqmaydigan kishidir.",note:"لَزِمَ دَارَهُ — uyida qolmoq, uyidan chiqmay turmoq."},
{num:107,time:"00:08:39,100 --> 00:08:41,899",arabic:"وَاعْتَزَلَ هَذَا الشَّرَّ وَالْخَوْضَ فِيهِ.",segs:[{ar:"وَاعْتَزَلَ هَذَا الشَّرَّ",uz:"Va bu yomonlikdan chetda turadi"},{ar:"وَالْخَوْضَ فِيهِ",uz:"hamda unga aralashishdan"}],full_uz:"Va bu yomonlikdan hamda unga aralashishdan chetda turadi.",note:"الْخَوْضُ فِي — bir ishga kirishish, unga aralashish."},
{num:108,time:"00:08:41,899 --> 00:08:43,879",arabic:"أَتُحَرِّضُ النَّاسَ عَلَى وَلِيِّ الْأَمْرِ؟",segs:[{ar:"أَتُحَرِّضُ النَّاسَ",uz:"Odamlarni gijgijlayapsizmi"},{ar:"عَلَى وَلِيِّ الْأَمْرِ",uz:"hukmdorga qarshi?"}],full_uz:"Odamlarni hukmdorga qarshi gijgijlayapsizmi?",note:"وَلِيُّ الْأَمْرِ — boshqaruv egasi, hukmdor."},
{num:109,time:"00:08:43,879 --> 00:08:46,580",arabic:"إِنْ لَمْ تَخَفْ مِنَ اللَّهِ فَخَفْ مِنَ الْعَسَسِ.",segs:[{ar:"إِنْ لَمْ تَخَفْ مِنَ اللَّهِ",uz:"Allohdan qo‘rqmasangiz"},{ar:"فَخَفْ مِنَ الْعَسَسِ",uz:"soqchilardan qo‘rqing"}],full_uz:"Allohdan qo‘rqmasangiz, soqchilardan qo‘rqing.",note:"الْعَسَسُ — ayniqsa tunda shaharni qo‘riqlab yuradigan soqchilar."},
{num:110,time:"00:08:46,580 --> 00:08:49,519",arabic:"إِلَى مَتَى نَحْنِي رُؤُوسَنَا أَمَامَ رِيَاحِ الظَّالِمِينَ؟",segs:[{ar:"إِلَى مَتَى نَحْنِي رُؤُوسَنَا",uz:"Qachongacha boshimizni egamiz"},{ar:"أَمَامَ رِيَاحِ الظَّالِمِينَ",uz:"zolimlarning shamollari qarshisida?"}],full_uz:"Qachongacha zolimlarning shamollari qarshisida boshimizni egamiz?",note:"نَحْنِي رُؤُوسَنَا — «boshimizni egamiz»; bu yerda bosimga bo‘ysunish timsoli."},
{num:111,time:"00:08:49,519 --> 00:08:51,500",arabic:"وَنَرْكُضُ خَلْفَ الطُّغَاةِ؟",segs:null,full_uz:"Va zolimlar ortidan yuguramiz?",note:"الطُّغَاةُ — طَاغِيَةٌ («zolim, mustabid») so‘zining ko‘pligi."},
{num:112,time:"00:08:51,500 --> 00:08:54,039",arabic:"قُولُوا لِي، إِلَى مَتَى؟",segs:[{ar:"قُولُوا لِي",uz:"Menga aytinglar"},{ar:"إِلَى مَتَى",uz:"qachongacha?"}],full_uz:"Menga aytinglar, qachongacha?",note:null},
{num:113,time:"00:08:54,039 --> 00:08:58,240",arabic:"هَلْ يَتَحَمَّلُ الْأَمِينُ أَوْ أَخُوهُ وِزْرَ خَطَايَانَا أَمَامَ اللَّهِ؟",segs:[{ar:"هَلْ يَتَحَمَّلُ الْأَمِينُ أَوْ أَخُوهُ",uz:"Amin yoki uning birodari ko‘taradimi"},{ar:"وِزْرَ خَطَايَانَا",uz:"xatolarimizning gunoh yukini"},{ar:"أَمَامَ اللَّهِ",uz:"Alloh huzurida?"}],full_uz:"Alloh huzurida xatolarimizning gunoh yukini Amin yoki uning birodari ko‘taradimi?",note:"وِزْرٌ — og‘ir yuk; ko‘pincha gunoh va uning javobgarligi ma’nosida."},
{num:114,time:"00:08:58,240 --> 00:09:00,379",arabic:"أَفِيقُوا أَيُّهَا الْمُسْلِمُونَ!",segs:null,full_uz:"Hushingizni yig‘inglar, ey musulmonlar!",note:"أَفَاقَ — يُفِيقُ — أَفِقْ: «hushiga keldi — hushiga keladi — hushingizni yig‘ing»."},
{num:115,time:"00:09:02,919 --> 00:09:04,759",arabic:"أَفِيقُوا أَيُّهَا النَّاسُ!",segs:null,full_uz:"Hushingizni yig‘inglar, ey odamlar!",note:null},
{num:116,time:"00:09:04,759 --> 00:09:05,759",arabic:"أَفِيقُوا!",segs:null,full_uz:"Hushingizni yig‘inglar!",note:null},
{num:117,time:"00:09:05,759 --> 00:09:07,639",arabic:"أَفِيقُوا! إِلَى مَتَى؟",segs:[{ar:"أَفِيقُوا",uz:"Hushingizni yig‘inglar!"},{ar:"إِلَى مَتَى",uz:"Qachongacha?"}],full_uz:"Hushingizni yig‘inglar! Qachongacha?",note:null},
{num:118,time:"00:09:07,639 --> 00:09:10,720",arabic:"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ.",segs:[{ar:"السَّلَامُ عَلَيْكُمْ",uz:"Sizlarga tinchlik bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ",uz:"va Allohning rahmati"}],full_uz:"Sizlarga tinchlik va Allohning rahmati bo‘lsin.",note:null},
{num:119,time:"00:09:13,820 --> 00:09:19,159",arabic:"اللَّهُمَّ اغْفِرْ لِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ.",segs:[{ar:"اللَّهُمَّ اغْفِرْ",uz:"Allohim, mag‘firat qil"},{ar:"لِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ",uz:"mo‘min erkaklar va mo‘mina ayollarni"}],full_uz:"Allohim, mo‘min erkaklar va mo‘mina ayollarni mag‘firat qil.",note:null},
{num:120,time:"00:09:19,159 --> 00:09:21,560",arabic:"وَالْمُسْلِمِينَ وَالْمُسْلِمَاتِ.",segs:null,full_uz:"Musulmon erkaklar va muslima ayollarni ham.",note:null},
{num:121,time:"00:09:21,560 --> 00:09:23,899",arabic:"وَأَلِّفْ بَيْنَ قُلُوبِهِمْ.",segs:null,full_uz:"Ularning qalblarini birlashtir.",note:"أَلَّفَ بَيْنَ الْقُلُوبِ — qalblarni mehr va ahillik bilan birlashtirmoq."},
{num:122,time:"00:09:23,899 --> 00:09:25,539",arabic:"وَأَصْلِحْ ذَاتَ بَيْنِهِمْ.",segs:null,full_uz:"Ularning o‘zaro munosabatlarini o‘ngla.",note:"ذَاتُ الْبَيْنِ — odamlar o‘rtasidagi munosabatlar."},
{num:123,time:"00:09:25,539 --> 00:09:27,840",arabic:"وَاهْدِهِمْ سُبُلَ السَّلَامِ.",segs:null,full_uz:"Ularni tinchlik yo‘llariga boshlagin.",note:"سُبُلٌ — سَبِيلٌ («yo‘l») so‘zining ko‘pligi."},
{num:124,time:"00:09:27,840 --> 00:09:32,240",arabic:"وَانْصُرْهُمْ عَلَى عَدُوِّكَ وَعَدُوِّهِمْ يَا أَرْحَمَ الرَّاحِمِينَ.",segs:[{ar:"وَانْصُرْهُمْ",uz:"Ularga g‘alaba ber"},{ar:"عَلَى عَدُوِّكَ وَعَدُوِّهِمْ",uz:"Sening va ularning dushmani ustidan"},{ar:"يَا أَرْحَمَ الرَّاحِمِينَ",uz:"ey rahm qiluvchilarning eng rahmlisi"}],full_uz:"Ey rahm qiluvchilarning eng rahmlisi, ularga Sening va ularning dushmani ustidan g‘alaba ber.",note:null},
{num:125,time:"00:09:32,240 --> 00:09:37,060",arabic:"اللَّهُمَّ أَبْرِمْ لِهَذِهِ الْأُمَّةِ أَمْرَ رُشْدٍ.",segs:[{ar:"اللَّهُمَّ أَبْرِمْ",uz:"Allohim, qaror toptir"},{ar:"لِهَذِهِ الْأُمَّةِ",uz:"bu ummat uchun"},{ar:"أَمْرَ رُشْدٍ",uz:"to‘g‘ri yo‘ldagi bir ishni"}],full_uz:"Allohim, bu ummat uchun to‘g‘ri yo‘ldagi ishni qaror toptir.",note:"أَبْرَمَ الْأَمْرَ — ishni mustahkam qarorga keltirmoq. رُشْدٌ — to‘g‘rilik, oqilona yo‘l."},
{num:126,time:"00:09:37,060 --> 00:09:39,460",arabic:"يَعِزُّ فِيهِ أَهْلُ طَاعَتِكَ.",segs:[{ar:"يَعِزُّ فِيهِ",uz:"Unda aziz bo‘lsin"},{ar:"أَهْلُ طَاعَتِكَ",uz:"Senga itoat qiluvchilar"}],full_uz:"Unda Senga itoat qiluvchilar aziz bo‘lsin.",note:null},
{num:127,time:"00:09:39,460 --> 00:09:42,060",arabic:"وَيَذِلُّ فِيهِ أَهْلُ عَدَاوَتِكَ.",segs:[{ar:"وَيَذِلُّ فِيهِ",uz:"Unda xor bo‘lsin"},{ar:"أَهْلُ عَدَاوَتِكَ",uz:"Senga dushmanlik qiluvchilar"}],full_uz:"Unda Senga dushmanlik qiluvchilar xor bo‘lsin.",note:null},
{num:128,time:"00:09:42,060 --> 00:09:44,879",arabic:"وَيُهْدَى فِيهِ أَهْلُ مَعْصِيَتِكَ.",segs:[{ar:"وَيُهْدَى فِيهِ",uz:"Unda hidoyatga boshlansin"},{ar:"أَهْلُ مَعْصِيَتِكَ",uz:"Senga osiylik qiluvchilar"}],full_uz:"Unda Senga osiylik qiluvchilar hidoyatga boshlansin.",note:"يُهْدَى — majhul nisbat: «hidoyatga boshlanadi»."},
{num:129,time:"00:09:44,879 --> 00:09:49,100",arabic:"وَيُؤْمَرُ فِيهِ بِالْمَعْرُوفِ وَيُنْهَى فِيهِ عَنِ الْمُنْكَرِ.",segs:[{ar:"وَيُؤْمَرُ فِيهِ بِالْمَعْرُوفِ",uz:"Unda yaxshilikka buyurilsin"},{ar:"وَيُنْهَى فِيهِ عَنِ الْمُنْكَرِ",uz:"va yomonlikdan qaytarilsin"}],full_uz:"Unda yaxshilikka buyurilib, yomonlikdan qaytarilsin.",note:"أَمَرَ بِـ — «...ga buyurmoq»; نَهَى عَنْ — «...dan qaytarmoq»."},
{num:130,time:"00:09:49,100 --> 00:09:51,480",arabic:"يَا رَبَّ الْعَالَمِينَ.",segs:null,full_uz:"Ey olamlarning Robbi.",note:null},
{num:131,time:"00:09:51,480 --> 00:09:55,480",arabic:"يَا رَبِّ.",segs:null,full_uz:"Ey Rabbim.",note:null},
{num:132,time:"00:09:55,480 --> 00:10:15,740",arabic:"لَمْ تَهْدَأِ الْأَصْوَاتُ مُنْذُ الْأَمْسِ.",segs:[{ar:"لَمْ تَهْدَأِ الْأَصْوَاتُ",uz:"Ovozlar tinmadi"},{ar:"مُنْذُ الْأَمْسِ",uz:"kechadan beri"}],full_uz:"Kechadan beri ovozlar tinmadi.",note:null},
{num:133,time:"00:10:15,740 --> 00:10:20,820",arabic:"أَرَأَيْتَ إِلَى أَيْنَ أَوْصَلَنَا الْخِلَافُ بَيْنَ الْأَمِينِ وَالْمَأْمُونِ؟",segs:[{ar:"أَرَأَيْتَ إِلَى أَيْنَ أَوْصَلَنَا",uz:"Bizni qayerga olib kelganini ko‘rdingizmi"},{ar:"الْخِلَافُ بَيْنَ الْأَمِينِ وَالْمَأْمُونِ",uz:"Amin bilan Ma’mun o‘rtasidagi ixtilof?"}],full_uz:"Amin bilan Ma’mun o‘rtasidagi ixtilof bizni qayerga olib kelganini ko‘rdingizmi?",note:null},
{num:134,time:"00:10:20,820 --> 00:10:23,159",arabic:"حَتَّى طَالَ صَلَاةَ الْجَمَاعَةِ.",segs:null,full_uz:"Hatto jamoat namoziga ham ta’siri yetdi.",note:"طَالَ الشَّيْءَ bu yerda «bir narsaga yetib bormoq, ta’sir qilmoq»; «uzoq davom etmoq» ma’nosida emas."},
{num:135,time:"00:10:23,159 --> 00:10:25,939",arabic:"اللَّهُ الْمُسْتَعَانُ.",segs:null,full_uz:"Yordam so‘raladigan zot Allohdir.",note:"الْمُسْتَعَانُ — yordam so‘raladigan zot; اِسْتَعَانَ fe’lidan."},
{num:136,time:"00:10:25,939 --> 00:10:29,559",arabic:"وَمَنْ يَجْرُؤُ الْآنَ عَلَى الْخُرُوجِ مِنْ بَيْتِهِ؟",segs:[{ar:"وَمَنْ يَجْرُؤُ الْآنَ",uz:"Endi kim jur’at qiladi"},{ar:"عَلَى الْخُرُوجِ مِنْ بَيْتِهِ",uz:"uyidan chiqishga?"}],full_uz:"Endi kim uyidan chiqishga jur’at qiladi?",note:"جَرُؤَ عَلَى — «...ga jur’at qilmoq»."},
{num:137,time:"00:10:29,559 --> 00:10:33,500",arabic:"بَعْدَ أَنْ فَقَدَتْ بَغْدَادُ الْأَمْنَ وَالْأَمَانَ.",segs:[{ar:"بَعْدَ أَنْ فَقَدَتْ بَغْدَادُ",uz:"Bag‘dod yo‘qotganidan keyin"},{ar:"الْأَمْنَ وَالْأَمَانَ",uz:"tinchlik va xavfsizlikni"}],full_uz:"Bag‘dod tinchlik va xavfsizlikni yo‘qotganidan keyin.",note:null},
{num:138,time:"00:10:33,500 --> 00:10:39,059",arabic:"أَيُّ بَلَاءٍ حَلَّ بِكِ يَا بَغْدَادُ؟",segs:[{ar:"أَيُّ بَلَاءٍ حَلَّ بِكِ",uz:"Boshingga qanday balo tushdi"},{ar:"يَا بَغْدَادُ",uz:"ey Bag‘dod?"}],full_uz:"Boshingga qanday balo tushdi, ey Bag‘dod?",note:"حَلَّ بِهِ بَلَاءٌ — «uning boshiga balo tushdi»."},
{num:139,time:"00:10:44,559 --> 00:10:49,059",arabic:"يَبْدُو أَنَّ الشُّطَّارَ وَالْعَيَّارِينَ...",segs:[{ar:"يَبْدُو أَنَّ",uz:"Aftidan"},{ar:"الشُّطَّارَ وَالْعَيَّارِينَ",uz:"bezorilar va ayyollar"}],full_uz:"Aftidan, bezorilar va ayyollar...",note:"الشُّطَّارُ وَالْعَيَّارُونَ — bu tarixiy muhitda ko‘cha bezorilari va talonchilik qiluvchi guruhlar; «ayyollar» ayollar degani emas, عَيَّارٌ so‘zining nomlanishi."},
{num:140,time:"00:10:49,059 --> 00:10:53,039",arabic:"قَدْ وَجَدُوا الْفُرْصَةَ سَانِحَةً أَمَامَهُمْ.",segs:[{ar:"قَدْ وَجَدُوا الْفُرْصَةَ",uz:"imkoniyatni topdilar"},{ar:"سَانِحَةً أَمَامَهُمْ",uz:"oldilarida qulay bo‘lib turgan"}],full_uz:"Oldilarida qulay imkoniyat paydo bo‘lganini ko‘rdilar.",note:"فُرْصَةٌ سَانِحَةٌ — qulay, yuzaga kelgan imkoniyat."},
{num:141,time:"00:10:53,039 --> 00:10:57,819",arabic:"فَلَمْ يَدَعُوا شَيْئًا إِلَّا وَأَخَذُوهُ.",segs:[{ar:"فَلَمْ يَدَعُوا شَيْئًا",uz:"Hech narsani qoldirmadilar"},{ar:"إِلَّا وَأَخَذُوهُ",uz:"hammasini oldilar"}],full_uz:"Hech narsani qoldirmay, hammasini oldilar.",note:"لَمْ يَدَعُوا — «qoldirmadilar»; وَدَعَ — يَدَعُ fe’lidan."},
{num:142,time:"00:10:57,819 --> 00:11:03,639",arabic:"وَلَمْ يَتْرُكُوا حَرَامًا إِلَّا وَانْتَهَكُوهُ.",segs:[{ar:"وَلَمْ يَتْرُكُوا حَرَامًا",uz:"Hech bir taqiqni qoldirmadilar"},{ar:"إِلَّا وَانْتَهَكُوهُ",uz:"hammasini buzdilar"}],full_uz:"Buzmagan taqiqlari qolmadi.",note:"اِنْتَهَكَ — daxlsizlikni yoki taqiqni buzmoq, oyoqosti qilmoq."},
{num:143,time:"00:11:03,639 --> 00:11:09,839",arabic:"مَا كَانَ أَغْنَى الْمُسْلِمِينَ عَنْ ذَلِكَ لَوْ أَنَّ أَبْنَاءَ الرَّشِيدِ رَضُوا بِمَا أَنْزَلَ اللَّهُ عَلَى رَسُولِهِ!",segs:[{ar:"مَا كَانَ أَغْنَى الْمُسْلِمِينَ عَنْ ذَلِكَ",uz:"Musulmonlar bunga naqadar muhtoj emas edilar"},{ar:"لَوْ أَنَّ أَبْنَاءَ الرَّشِيدِ رَضُوا",uz:"agar Rashidning o‘g‘illari rozi bo‘lganida"},{ar:"بِمَا أَنْزَلَ اللَّهُ عَلَى رَسُولِهِ",uz:"Alloh Rasuliga nozil qilgan narsaga!"}],full_uz:"Agar Rashidning o‘g‘illari Alloh Rasuliga nozil qilgan narsaga rozi bo‘lganida, musulmonlar bu balolardan naqadar xoli bo‘lardilar!",note:"مَا أَغْنَاهُ عَنْ ذَلِكَ! — «bunga uning hech qanday hojati yo‘q edi!» mazmunidagi taajjub."},
{num:144,time:"00:11:09,839 --> 00:11:13,240",arabic:"وَغَلَّبُوا الْمَصْلَحَةَ الْعَامَّةَ عَلَى الْخَاصَّةِ.",segs:[{ar:"وَغَلَّبُوا الْمَصْلَحَةَ الْعَامَّةَ",uz:"Va umumiy manfaatni ustun qo‘yganlarida"},{ar:"عَلَى الْخَاصَّةِ",uz:"shaxsiy manfaatdan"}],full_uz:"Va umumiy manfaatni shaxsiy manfaatdan ustun qo‘yganlarida.",note:null},
{num:145,time:"00:11:13,240 --> 00:11:16,379",arabic:"وَلَكِنْ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.",segs:[{ar:"وَلَكِنْ لَا حَوْلَ وَلَا قُوَّةَ",uz:"Ammo hech qanday kuch va qudrat yo‘q"},{ar:"إِلَّا بِاللَّهِ",uz:"faqat Alloh bilangina bor"}],full_uz:"Ammo kuch va qudrat faqat Alloh bilandir.",note:null},
{num:146,time:"00:11:16,379 --> 00:11:21,899",arabic:"إِنَّ مَنْ يَدْفَعُ الثَّمَنَ الْآنَ قَوْمٌ لَا نَاقَةَ لَهُمْ وَلَا جَمَلَ فِي هَذِهِ الْحَرْبِ.",segs:[{ar:"إِنَّ مَنْ يَدْفَعُ الثَّمَنَ الْآنَ",uz:"Hozir badalni to‘layotganlar"},{ar:"قَوْمٌ لَا نَاقَةَ لَهُمْ وَلَا جَمَلَ",uz:"hech qanday daxli yo‘q odamlardir"},{ar:"فِي هَذِهِ الْحَرْبِ",uz:"bu urushga"}],full_uz:"Hozir bu urushga hech qanday daxli yo‘q odamlar uning badalini to‘layapti.",note:"لَا نَاقَةَ لَهُ وَلَا جَمَلَ — so‘zma-so‘z «uning na urg‘ochi, na erkak tuyasi bor»; «bu ishga daxli yoki manfaati yo‘q» degan ibora."},
{num:147,time:"00:11:21,899 --> 00:11:26,720",arabic:"اللَّهُمَّ احْقِنْ دِمَاءَ الْمُسْلِمِينَ.",segs:[{ar:"اللَّهُمَّ احْقِنْ",uz:"Allohim, saqla"},{ar:"دِمَاءَ الْمُسْلِمِينَ",uz:"musulmonlarning qonlarini"}],full_uz:"Allohim, musulmonlarning qonlari to‘kilishidan saqla.",note:null},
{num:148,time:"00:11:26,720 --> 00:11:29,419",arabic:"وَاكْفِنَا شَرَّ الْفِتَنِ.",segs:null,full_uz:"Bizni fitnalarning yomonligidan asra.",note:"كَفَى — يَكْفِي — اِكْفِ: «kifoya qildi — kifoya qiladi — kifoya qil»; duoda yomonlikdan himoya qilish so‘raladi."},
{num:149,time:"00:11:29,419 --> 00:11:32,860",arabic:"مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ.",segs:[{ar:"مَا ظَهَرَ مِنْهَا",uz:"Ularning oshkor bo‘lganidan"},{ar:"وَمَا بَطَنَ",uz:"va yashirin bo‘lganidan"}],full_uz:"Ularning oshkor va yashirin bo‘lganlaridan.",note:null},
{num:150,time:"00:11:32,860 --> 00:11:36,279",arabic:"وَاجْمَعْ كَلِمَتَهُمْ عَلَى سَوَاءٍ.",segs:[{ar:"وَاجْمَعْ كَلِمَتَهُمْ",uz:"Ularning so‘zini birlashtir"},{ar:"عَلَى سَوَاءٍ",uz:"bir to‘g‘ri yo‘lda"}],full_uz:"Ularni bir to‘g‘ri yo‘lda hamfikr qil.",note:"جَمَعَ كَلِمَتَهُمْ — ularni hamfikr va hamjihat qilmoq."},
{num:151,time:"00:11:36,279 --> 00:11:39,340",arabic:"وَاحْفَظْ لَنَا الْحُرُمَاتِ.",segs:null,full_uz:"Muqaddas va daxlsiz narsalarimizni biz uchun asra.",note:"الْحُرُمَاتُ — hurmat qilinishi, daxlsizligi saqlanishi lozim bo‘lgan narsalar."},
{num:152,time:"00:11:39,340 --> 00:11:42,360",arabic:"وَكُفَّ عَنَّا الْكُرُبَاتِ.",segs:null,full_uz:"Musibatlarni bizdan uzoq qil.",note:"كُرُبَاتٌ — og‘ir tashvishlar, musibatlar."},
{num:153,time:"00:11:42,360 --> 00:11:44,740",arabic:"اللَّهُمَّ آمِينَ.",segs:null,full_uz:"Allohim, qabul qil.",note:null},
{num:154,time:"00:11:44,740 --> 00:11:46,059",arabic:"آمِينَ.",segs:null,full_uz:"Omin.",note:null},
{num:155,time:"00:11:51,899 --> 00:11:55,340",arabic:"أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ.",segs:[{ar:"أَعُوذُ بِاللَّهِ",uz:"Allohdan panoh so‘rayman"},{ar:"مِنَ الشَّيْطَانِ الرَّجِيمِ",uz:"quvilgan shaytondan"}],full_uz:"Quvilgan shaytondan Allohdan panoh so‘rayman.",note:"عَاذَ بِـ — يَعُوذُ بِـ: «...dan panoh so‘ramoq»."},
{num:156,time:"00:11:55,340 --> 00:11:57,959",arabic:"بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ.",segs:null,full_uz:"Mehribon va rahmli Alloh nomi bilan.",note:null},
{num:157,time:"00:12:51,899 --> 00:12:56,899",arabic:"وَالِدِي، وَالِدِي، أَيْنَ أَنْتَ يَا وَالِدِي؟",segs:[{ar:"وَالِدِي، وَالِدِي",uz:"Otajon, otajon"},{ar:"أَيْنَ أَنْتَ يَا وَالِدِي",uz:"qayerdasiz, otajon?"}],full_uz:"Otajon, otajon, qayerdasiz, otajon?",note:null},
{num:158,time:"00:12:56,899 --> 00:12:59,899",arabic:"وَالِدِي! هَلْ رَأَيْتَ وَالِدِي؟",segs:[{ar:"وَالِدِي",uz:"Otajon!"},{ar:"هَلْ رَأَيْتَ وَالِدِي",uz:"Otamni ko‘rdingizmi?"}],full_uz:"Otajon! Otamni ko‘rdingizmi?",note:null},
{num:159,time:"00:13:47,899 --> 00:13:52,059",arabic:"إِنَّ أَهْلَ الْمَدِينَةِ يَتْرُكُونَ بُيُوتَهُمْ وَيَفِرُّونَ.",segs:[{ar:"إِنَّ أَهْلَ الْمَدِينَةِ",uz:"Shahar aholisi"},{ar:"يَتْرُكُونَ بُيُوتَهُمْ",uz:"uylarini tashlab ketyapti"},{ar:"وَيَفِرُّونَ",uz:"va qochyapti"}],full_uz:"Shahar aholisi uylarini tashlab qochyapti.",note:null},
{num:160,time:"00:13:52,059 --> 00:13:55,579",arabic:"إِلَى أَيْنَ يَفِرُّونَ؟",segs:null,full_uz:"Qayerga qochishyapti?",note:null},
{num:161,time:"00:13:55,579 --> 00:14:00,459",arabic:"إِنَّهُمْ خَائِفُونَ مِنْ جُنْدِ طَاهِرِ بْنِ الْحُسَيْنِ، مِنْ دُخُولِ الْمَدِينَةِ وَاسْتِبَاحَتِهَا.",segs:[{ar:"إِنَّهُمْ خَائِفُونَ",uz:"Ular qo‘rqishyapti"},{ar:"مِنْ جُنْدِ طَاهِرِ بْنِ الْحُسَيْنِ",uz:"Tohir ibn Husaynning askarlaridan"},{ar:"مِنْ دُخُولِ الْمَدِينَةِ",uz:"shaharga kirishidan"},{ar:"وَاسْتِبَاحَتِهَا",uz:"va uni talon-toroj qilishidan"}],full_uz:"Ular Tohir ibn Husayn askarlarining shaharga kirib, uni talon-toroj qilishidan qo‘rqishyapti.",note:"اِسْتِبَاحَةُ الْمَدِينَةِ — shaharning daxlsizligini poymol qilib, unda talonchilik va zo‘ravonlik qilish."},
{num:162,time:"00:14:00,459 --> 00:14:04,360",arabic:"فَلْيَذْهَبِ ابْنُ الْحُسَيْنِ إِلَى الْجَحِيمِ!",segs:[{ar:"فَلْيَذْهَبِ ابْنُ الْحُسَيْنِ",uz:"Ibn Husayn ketsin"},{ar:"إِلَى الْجَحِيمِ",uz:"jahannamga!"}],full_uz:"Ibn Husayn jahannamga ketsin!",note:null},
{num:163,time:"00:14:04,360 --> 00:14:14,019",arabic:"أَيْنَ الْجُنْدُ؟ أَيْنَ الْقَادَةُ؟ أَيْنَ الْأُمَرَاءُ؟ أَيْنَ هُمْ؟",segs:[{ar:"أَيْنَ الْجُنْدُ",uz:"Askarlar qayerda?"},{ar:"أَيْنَ الْقَادَةُ",uz:"Qo‘mondonlar qayerda?"},{ar:"أَيْنَ الْأُمَرَاءُ",uz:"Amirlar qayerda?"},{ar:"أَيْنَ هُمْ",uz:"Ular qayerda?"}],full_uz:"Askarlar qayerda? Qo‘mondonlar qayerda? Amirlar qayerda? Ular qayerda?",note:null},
{num:164,time:"00:14:14,019 --> 00:14:17,000",arabic:"لَقَدْ فَرَّ أَكْثَرُ جُنْدِكَ إِلَى طَاهِرِ بْنِ الْحُسَيْنِ.",segs:[{ar:"لَقَدْ فَرَّ أَكْثَرُ جُنْدِكَ",uz:"Askarlaringizning ko‘pchiligi qochib o‘tdi"},{ar:"إِلَى طَاهِرِ بْنِ الْحُسَيْنِ",uz:"Tohir ibn Husayn tomoniga"}],full_uz:"Askarlaringizning ko‘pchiligi Tohir ibn Husayn tomoniga qochib o‘tdi.",note:null},
{num:165,time:"00:14:17,000 --> 00:14:18,759",arabic:"وَأَخَذَ مِنْهُ الْأَمَانَ.",segs:null,full_uz:"Va undan omonlik kafolati oldi.",note:"أَخَذَ الْأَمَانَ — zarar yetkazilmasligi haqida kafolat olmoq."},
{num:166,time:"00:14:18,759 --> 00:14:22,039",arabic:"وَهُمْ يُقَاتِلُونَ الْآنَ فِي صُفُوفِ جَيْشِهِ.",segs:[{ar:"وَهُمْ يُقَاتِلُونَ الْآنَ",uz:"Ular hozir jang qilyapti"},{ar:"فِي صُفُوفِ جَيْشِهِ",uz:"uning qo‘shini safida"}],full_uz:"Ular hozir uning qo‘shini safida jang qilyapti.",note:null},
{num:167,time:"00:14:22,039 --> 00:14:24,319",arabic:"سُحْقًا لَهُ وَلَهُمْ!",segs:null,full_uz:"U ham, ular ham yo‘q bo‘lsin!",note:"سُحْقًا لِـ — qarg‘ish va qattiq nafrat ifodasi."},
{num:168,time:"00:14:24,319 --> 00:14:33,019",arabic:"مِنْ أَيْنَ آتِي بِحَظٍّ كَحَظِّ طَاهِرِ بْنِ الْحُسَيْنِ؟",segs:[{ar:"مِنْ أَيْنَ آتِي بِحَظٍّ",uz:"Qayerdan topaman bir omadni"},{ar:"كَحَظِّ طَاهِرِ بْنِ الْحُسَيْنِ",uz:"Tohir ibn Husaynning omadidek?"}],full_uz:"Tohir ibn Husaynning omadidek omadni qayerdan topaman?",note:null},
{num:169,time:"00:14:34,539 --> 00:14:35,740",arabic:"إِنَّ جُنْدِيًّا مِنْ جُنُودِي...",segs:null,full_uz:"Askarlarimdan bittasi...",note:null},
{num:170,time:"00:14:35,740 --> 00:14:39,679",arabic:"يَأْخُذُ نَفَقَةً أَضْعَافَ مَا يَأْخُذُ طَاهِرٌ مِنَ الْمَأْمُونِ.",segs:[{ar:"يَأْخُذُ نَفَقَةً",uz:"mablag‘ oladi"},{ar:"أَضْعَافَ مَا يَأْخُذُ طَاهِرٌ",uz:"Tohir oladiganidan bir necha baravar ko‘p"},{ar:"مِنَ الْمَأْمُونِ",uz:"Ma’mundan"}],full_uz:"Tohir Ma’mundan oladiganidan bir necha baravar ko‘p mablag‘ oladi.",note:"أَضْعَافَ — bir necha baravar; ضِعْفٌ so‘zining ko‘pligi."},
{num:171,time:"00:14:39,679 --> 00:14:43,019",arabic:"وَهُمْ يَفِرُّونَ كَالْجِرْذَانِ.",segs:null,full_uz:"Ular esa kalamushlardek qochishyapti.",note:"جِرْذَانٌ — جُرَذٌ («kalamush») so‘zining ko‘pligi."},
{num:172,time:"00:14:44,019 --> 00:14:47,460",arabic:"أَعُوذُ بِاللَّهِ مِنَ الْخِذْلَانِ.",segs:[{ar:"أَعُوذُ بِاللَّهِ",uz:"Allohdan panoh so‘rayman"},{ar:"مِنَ الْخِذْلَانِ",uz:"yordamsiz tashlab qo‘yilishdan"}],full_uz:"Yordamsiz tashlab qo‘yilishdan Allohdan panoh so‘rayman.",note:"خِذْلَانٌ — zarur paytda yordamdan mahrum qolish, tashlab ketilish."},
{num:173,time:"00:14:49,879 --> 00:14:51,360",arabic:"وَمِنَ الذُّلِّ.",segs:null,full_uz:"Va xorlikdan.",note:null},
{num:174,time:"00:14:51,360 --> 00:14:52,899",arabic:"وَقَهْرِ الرِّجَالِ.",segs:null,full_uz:"Va odamlarning zo‘ravonligidan.",note:"قَهْرُ الرِّجَالِ — odamlarning bosimi, zo‘ravonligi ostida qolish."},
{num:175,time:"00:14:52,899 --> 00:14:58,360",arabic:"السَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ.",segs:null,full_uz:"Mo‘minlar amiriga salom bo‘lsin.",note:null},
{num:176,time:"00:14:58,360 --> 00:15:00,019",arabic:"وَجَدْتَهُ؟",segs:null,full_uz:"Uni topdingizmi?",note:null},
{num:177,time:"00:15:00,019 --> 00:15:01,419",arabic:"بَحَثْتُ عَنْهُ فِي كُلِّ مَكَانٍ.",segs:[{ar:"بَحَثْتُ عَنْهُ",uz:"Uni qidirdim"},{ar:"فِي كُلِّ مَكَانٍ",uz:"hamma joyda"}],full_uz:"Uni hamma joydan qidirdim.",note:null},
{num:178,time:"00:15:01,419 --> 00:15:04,840",arabic:"وَلَمْ أَجِدْهُ.",segs:null,full_uz:"Ammo topmadim.",note:null},
{num:179,time:"00:15:04,840 --> 00:15:07,019",arabic:"أَيْنَ ذَهَبَ؟",segs:null,full_uz:"Qayerga ketdi?",note:null},
{num:180,time:"00:15:07,019 --> 00:15:09,019",arabic:"أَيْنَ ذَهَبَ ابْنُ الرَّبِيعِ هَذَا؟",segs:null,full_uz:"Bu Ibn Rabi’ qayerga ketdi?",note:null},
{num:181,time:"00:15:11,159 --> 00:15:13,779",arabic:"وَلَكِنْ...",segs:null,full_uz:"Ammo...",note:null},
{num:182,time:"00:15:13,779 --> 00:15:21,500",arabic:"جِدْهُ لِي يَا مَسْرُورُ.",segs:null,full_uz:"Uni menga topib bering, Masrur.",note:"جِدْ — وَجَدَ — يَجِدُ fe’lining buyruq shakli: «top»."},
{num:183,time:"00:15:21,500 --> 00:15:24,360",arabic:"فَتِّشْ عَنْهُ فِي كُلِّ مَكَانٍ.",segs:[{ar:"فَتِّشْ عَنْهُ",uz:"Uni qidiring"},{ar:"فِي كُلِّ مَكَانٍ",uz:"hamma joydan"}],full_uz:"Uni hamma joydan qidiring.",note:null},
{num:184,time:"00:15:24,360 --> 00:15:26,879",arabic:"أُرِيدُهُ الْآنَ أَمَامِي.",segs:[{ar:"أُرِيدُهُ الْآنَ",uz:"Uni hozir istayman"},{ar:"أَمَامِي",uz:"oldimda"}],full_uz:"Uni hoziroq oldimda ko‘rishni istayman.",note:null},
{num:185,time:"00:15:26,879 --> 00:15:28,419",arabic:"السَّمْعُ وَالطَّاعَةُ.",segs:null,full_uz:"Eshitdim va itoat qilaman.",note:"السَّمْعُ وَالطَّاعَةُ — buyruqni bajarishga tayyorlik bildiruvchi ibora."},
{num:186,time:"00:15:28,419 --> 00:15:34,919",arabic:"السَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ وَصَحْبِهِ.",segs:[{ar:"السَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ",uz:"Mo‘minlar amiriga salom bo‘lsin"},{ar:"وَصَحْبِهِ",uz:"va uning hamrohlariga"}],full_uz:"Mo‘minlar amiri va uning hamrohlariga salom bo‘lsin.",note:null},
{num:187,time:"00:15:34,919 --> 00:15:36,139",arabic:"وَعَلَيْكُمُ السَّلَامُ.",segs:null,full_uz:"Sizlarga ham salom bo‘lsin.",note:null},
{num:188,time:"00:15:36,139 --> 00:15:38,559",arabic:"وَزِيرُكَ الْفَضْلُ بْنُ الرَّبِيعِ يَا مَوْلَايَ...",segs:[{ar:"وَزِيرُكَ الْفَضْلُ بْنُ الرَّبِيعِ",uz:"Vaziringiz Fazl ibn Rabi’"},{ar:"يَا مَوْلَايَ",uz:"hazratim"}],full_uz:"Vaziringiz Fazl ibn Rabi’, hazratim...",note:null},
{num:189,time:"00:15:38,559 --> 00:15:40,019",arabic:"هَرَبَ.",segs:null,full_uz:"Qochib ketdi.",note:null},
{num:190,time:"00:15:47,600 --> 00:15:54,699",arabic:"هَرَبَ بَعْدَ أَنْ زَيَّنَ لِي خَلْعَ الْمَأْمُونِ.",segs:[{ar:"هَرَبَ",uz:"Qochib ketdi"},{ar:"بَعْدَ أَنْ زَيَّنَ لِي",uz:"menga yaxshi qilib ko‘rsatganidan keyin"},{ar:"خَلْعَ الْمَأْمُونِ",uz:"Ma’munni lavozimidan chetlatishni"}],full_uz:"Ma’munni lavozimidan chetlatishni menga yaxshi qilib ko‘rsatganidan keyin qochib ketdi.",note:"زَيَّنَ لَهُ الْأَمْرَ — bir ishni unga ma’qul va chiroyli qilib ko‘rsatmoq."},
{num:191,time:"00:15:54,699 --> 00:15:58,740",arabic:"وَالْبَيْعَةَ لِابْنِي مُوسَى وَلِيًّا لِلْعَهْدِ.",segs:[{ar:"وَالْبَيْعَةَ لِابْنِي مُوسَى",uz:"Va o‘g‘lim Musoga bay’at qilishni"},{ar:"وَلِيًّا لِلْعَهْدِ",uz:"valiahd sifatida"}],full_uz:"Va o‘g‘lim Musoga valiahd sifatida bay’at qilishni.",note:"وَلِيُّ الْعَهْدِ — taxt vorisi."},
{num:192,time:"00:16:07,539 --> 00:16:08,740",arabic:"تَبًّا!",segs:null,full_uz:"La’nati!",note:"تَبًّا — g‘azab yoki qarg‘ish ifodasi."},
{num:193,time:"00:16:08,740 --> 00:16:11,220",arabic:"كُلُّهُمْ أَرْوَغُ مِنْ ثَعْلَبٍ.",segs:[{ar:"كُلُّهُمْ أَرْوَغُ",uz:"Hammasi ayyorroq"},{ar:"مِنْ ثَعْلَبٍ",uz:"tulkidan"}],full_uz:"Hammasi tulkidan ham ayyor.",note:"أَرْوَغُ — ayyorroq, hiyla bilan qochib qolishga ustaroq."},
{num:194,time:"00:16:11,220 --> 00:16:17,220",arabic:"مَا أَشْبَهَ اللَّيْلَةَ بِالْبَارِحَةِ!",segs:[{ar:"مَا أَشْبَهَ اللَّيْلَةَ",uz:"Bu kecha naqadar o‘xshaydi"},{ar:"بِالْبَارِحَةِ",uz:"kechagi kechaga!"}],full_uz:"Bu kecha kechagi kechaga naqadar o‘xshaydi!",note:"Takrorlanayotgan voqealar haqida aytiladigan ibora. مَا أَفْعَلَ — taajjub qolipi."},
{num:195,time:"00:19:26,380 --> 00:19:31,000",arabic:"اللَّهُمَّ اكْشِفْ هَذِهِ الْغُمَّةَ وَجَنِّبِ الْمُسْلِمِينَ الْفِتَنَ.",segs:[{ar:"اللَّهُمَّ اكْشِفْ هَذِهِ الْغُمَّةَ",uz:"Allohim, bu g‘amni arit"},{ar:"وَجَنِّبِ الْمُسْلِمِينَ الْفِتَنَ",uz:"va musulmonlarni fitnalardan uzoq qil"}],full_uz:"Allohim, bu g‘amni arit va musulmonlarni fitnalardan uzoq qil.",note:"كَشَفَ الْغُمَّةَ — g‘am va og‘irlikni ketkazmoq. جَنَّبَهُ الشَّيْءَ — uni bir narsadan uzoq tutmoq."},
{num:196,time:"00:19:31,000 --> 00:19:46,299",arabic:"جِئْتُ أَطْمَئِنُّ عَلَيْكُمْ، هَلِ الْجَمِيعُ بِخَيْرٍ؟",segs:[{ar:"جِئْتُ أَطْمَئِنُّ عَلَيْكُمْ",uz:"Holingizdan xabar olgani keldim"},{ar:"هَلِ الْجَمِيعُ بِخَيْرٍ",uz:"hamma yaxshimi?"}],full_uz:"Holingizdan xabar olgani keldim. Hamma yaxshimi?",note:"اِطْمَأَنَّ عَلَى فُلَانٍ — birovning sog‘-omonligini bilib, ko‘ngli tinchimoq."},
{num:197,time:"00:19:46,299 --> 00:19:48,799",arabic:"حَتَّى الْآنَ بِخَيْرٍ، نَتَهَيَّأُ لِنَخْرُجَ مِنْ هُنَا.",segs:[{ar:"حَتَّى الْآنَ بِخَيْرٍ",uz:"Hozircha yaxshimiz"},{ar:"نَتَهَيَّأُ لِنَخْرُجَ مِنْ هُنَا",uz:"bu yerdan chiqishga tayyorlanyapmiz"}],full_uz:"Hozircha yaxshimiz. Bu yerdan chiqishga tayyorlanyapmiz.",note:null},
{num:198,time:"00:19:48,799 --> 00:19:50,700",arabic:"اِذْهَبْ وَأَحْضِرْ أُمَّكَ لِنُغَادِرَ سَوِيًّا.",segs:[{ar:"اِذْهَبْ وَأَحْضِرْ أُمَّكَ",uz:"Borib, onangizni olib keling"},{ar:"لِنُغَادِرَ سَوِيًّا",uz:"birga ketishimiz uchun"}],full_uz:"Borib, onangizni olib keling, birga ketaylik.",note:"سَوِيًّا — birga, birgalikda."},
{num:199,time:"00:19:50,700 --> 00:19:53,259",arabic:"أَيْنَ سَنَذْهَبُ؟ أَنَفِرُّ كَمَا فَرَّ النَّاسُ؟",segs:[{ar:"أَيْنَ سَنَذْهَبُ",uz:"Qayerga boramiz?"},{ar:"أَنَفِرُّ",uz:"Qochamizmi"},{ar:"كَمَا فَرَّ النَّاسُ",uz:"odamlar qochganidek?"}],full_uz:"Qayerga boramiz? Odamlar qochganidek qochamizmi?",note:"أَنَفِرُّ tarkibidagi أَ so‘roq yuklamasi; نَفِرُّ — «biz qochamiz»."},
{num:200,time:"00:19:53,259 --> 00:19:55,640",arabic:"نَخْرُجُ مِنْ هَذِهِ الْفَوْضَى وَهَذَا الدَّمَارِ.",segs:[{ar:"نَخْرُجُ مِنْ هَذِهِ الْفَوْضَى",uz:"Bu tartibsizlikdan chiqamiz"},{ar:"وَهَذَا الدَّمَارِ",uz:"va bu vayronagarchilikdan"}],full_uz:"Bu tartibsizlik va vayronagarchilikdan chiqamiz.",note:null},
{num:201,time:"00:19:55,640 --> 00:19:57,840",arabic:"نَفِرُّ مِنْ قَدَرِ اللَّهِ إِلَى قَدَرِ اللَّهِ.",segs:[{ar:"نَفِرُّ مِنْ قَدَرِ اللَّهِ",uz:"Allohning taqdiridan qochamiz"},{ar:"إِلَى قَدَرِ اللَّهِ",uz:"Allohning taqdiriga"}],full_uz:"Allohning taqdiridan Allohning taqdiriga qochamiz.",note:null},
{num:202,time:"00:19:57,840 --> 00:19:59,840",arabic:"خُرُوجُنَا وَبَقَاؤُنَا سَوَاءٌ.",segs:null,full_uz:"Ketishimiz ham, qolishimiz ham barobar.",note:"سَوَاءٌ — teng, bir xil."},
{num:203,time:"00:19:59,840 --> 00:20:01,960",arabic:"لَنْ نُغَادِرَ بَغْدَادَ مَهْمَا حَدَثَ.",segs:[{ar:"لَنْ نُغَادِرَ بَغْدَادَ",uz:"Bag‘dodni tark etmaymiz"},{ar:"مَهْمَا حَدَثَ",uz:"nima bo‘lishidan qat’i nazar"}],full_uz:"Nima bo‘lishidan qat’i nazar, Bag‘dodni tark etmaymiz.",note:"مَهْمَا حَدَثَ — nima bo‘lmasin."},
{num:204,time:"00:20:01,960 --> 00:20:03,880",arabic:"وَاحَسْرَتَاهُ عَلَى بَغْدَادَ!",segs:null,full_uz:"Voy, Bag‘dodga qanchalar achinaman!",note:"وَاحَسْرَتَاهُ — kuchli hasrat va achinish ifodasi."},
{num:205,time:"00:20:06,360 --> 00:20:07,920",arabic:"حَسْبِيَ اللَّهُ وَنِعْمَ الْوَكِيلُ.",segs:[{ar:"حَسْبِيَ اللَّهُ",uz:"Menga Alloh kifoya"},{ar:"وَنِعْمَ الْوَكِيلُ",uz:"U qanday ham yaxshi vakil"}],full_uz:"Menga Alloh kifoya, U qanday ham yaxshi vakil.",note:"الْوَكِيلُ — ish ishonib topshiriladigan zot."},
{num:206,time:"00:20:50,700 --> 00:20:52,340",arabic:"أَلَمْ يَكُنْ أَفْضَلَ؟",segs:null,full_uz:"Yaxshiroq bo‘lmasmidi?",note:null},
{num:207,time:"00:20:52,340 --> 00:20:54,779",arabic:"الْمَوْتُ صَارَ فِي كُلِّ مَكَانٍ يَا فَوْزُ.",segs:[{ar:"الْمَوْتُ صَارَ فِي كُلِّ مَكَانٍ",uz:"O‘lim hamma joyda bo‘lib qoldi"},{ar:"يَا فَوْزُ",uz:"ey Favz"}],full_uz:"O‘lim hamma joyda bo‘lib qoldi, Favz.",note:null},
{num:208,time:"00:20:54,779 --> 00:20:56,740",arabic:"وَمَا يُوجِعُ قَلْبِي...",segs:null,full_uz:"Yuragimni og‘ritadigan narsa esa...",note:null},
{num:209,time:"00:20:56,740 --> 00:20:58,840",arabic:"أَنَّ الْقَاتِلَ مُسْلِمٌ.",segs:null,full_uz:"Qotilning musulmon ekanligi.",note:null},
{num:210,time:"00:20:58,840 --> 00:21:00,840",arabic:"وَالْمَقْتُولُ مُسْلِمٌ.",segs:null,full_uz:"O‘ldirilgan ham musulmon.",note:"قَاتِلٌ — o‘ldiruvchi; مَقْتُولٌ — o‘ldirilgan."},
{num:211,time:"00:21:00,840 --> 00:21:05,740",arabic:"كَثِيرٌ مِنَ الْأَبْرِيَاءِ يُقْتَلُونَ دُونَ أَيِّ ذَنْبٍ.",segs:[{ar:"كَثِيرٌ مِنَ الْأَبْرِيَاءِ يُقْتَلُونَ",uz:"Ko‘p begunohlar o‘ldirilyapti"},{ar:"دُونَ أَيِّ ذَنْبٍ",uz:"hech qanday aybsiz"}],full_uz:"Ko‘p begunohlar hech qanday aybsiz o‘ldirilyapti.",note:"أَبْرِيَاءُ — بَرِيءٌ («begunoh») so‘zining ko‘pligi."},
{num:212,time:"00:21:50,700 --> 00:22:05,400",arabic:"لَنْ يَكُفُّوا حَتَّى يَجْعَلُوهَا رُكَامًا فَوْقَ رُؤُوسِنَا.",segs:[{ar:"لَنْ يَكُفُّوا",uz:"Ular to‘xtamaydilar"},{ar:"حَتَّى يَجْعَلُوهَا رُكَامًا",uz:"uni vayronalar uyumiga aylantirmaguncha"},{ar:"فَوْقَ رُؤُوسِنَا",uz:"boshimiz ustida"}],full_uz:"Uni boshimiz ustida vayronalar uyumiga aylantirmaguncha to‘xtamaydilar.",note:"رُكَامٌ — ustma-ust uyulgan narsalar, vayronalar uyumi."},
{num:213,time:"00:22:05,400 --> 00:22:08,059",arabic:"لَيْتَنَا خَرَجْنَا بِالْأَمْسِ.",segs:null,full_uz:"Qaniydi kecha chiqib ketganimizda.",note:null},
{num:214,time:"00:22:12,940 --> 00:22:15,100",arabic:"لَمْ تَكُنِ الدُّرُوبُ آمِنَةً.",segs:null,full_uz:"Yo‘llar xavfsiz emas edi.",note:null},
{num:215,time:"00:22:15,100 --> 00:22:18,039",arabic:"إِنَّهُمْ يُطَوِّقُونَ بَغْدَادَ مِنْ كُلِّ طَرَفٍ.",segs:[{ar:"إِنَّهُمْ يُطَوِّقُونَ بَغْدَادَ",uz:"Ular Bag‘dodni qurshab olyaptilar"},{ar:"مِنْ كُلِّ طَرَفٍ",uz:"har tomondan"}],full_uz:"Ular Bag‘dodni har tomondan qurshab olyaptilar.",note:null},
{num:216,time:"00:22:18,039 --> 00:22:20,660",arabic:"وَيُغْلِقُونَ جَمِيعَ مَنَافِذِهَا.",segs:null,full_uz:"Va uning barcha chiqish yo‘llarini to‘syaptilar.",note:"مَنَافِذُ — مَنْفَذٌ («chiqish yoki o‘tish joyi») so‘zining ko‘pligi."},
{num:217,time:"00:22:20,660 --> 00:22:24,160",arabic:"وَهَلْ سَتَنْتَظِرُ حَتَّى يُلْقُوا الْقَبْضَ عَلَيْكَ فِي قَصْرِكَ؟",segs:[{ar:"وَهَلْ سَتَنْتَظِرُ",uz:"Kutib turasizmi"},{ar:"حَتَّى يُلْقُوا الْقَبْضَ عَلَيْكَ",uz:"sizni qo‘lga olishguncha"},{ar:"فِي قَصْرِكَ",uz:"saroyingizda?"}],full_uz:"Sizni saroyingizda qo‘lga olishguncha kutib turasizmi?",note:"أَلْقَى الْقَبْضَ عَلَى — qo‘lga olmoq, hibsga olmoq."},
{num:218,time:"00:22:24,160 --> 00:22:26,519",arabic:"أَوْ يَجْعَلُوهُ رُكَامًا فَوْقَ رُؤُوسِنَا؟",segs:[{ar:"أَوْ يَجْعَلُوهُ رُكَامًا",uz:"Yoki uni vayronalar uyumiga aylantirishguncha"},{ar:"فَوْقَ رُؤُوسِنَا",uz:"boshimiz ustida?"}],full_uz:"Yoki uni boshimiz ustida vayronalar uyumiga aylantirishguncha?",note:null},
{num:219,time:"00:22:26,519 --> 00:22:27,920",arabic:"وَمَا عَسَايَ أَنْ أَفْعَلَ؟",segs:null,full_uz:"Men nima ham qila olardim?",note:"مَا عَسَايَ أَنْ أَفْعَلَ؟ — chorasizlikni bildiruvchi savol."},
{num:220,time:"00:22:27,920 --> 00:22:32,300",arabic:"إِنَّنِي هُنَا لَا حَوْلَ لِي وَلَا قُوَّةَ.",segs:[{ar:"إِنَّنِي هُنَا",uz:"Men bu yerda"},{ar:"لَا حَوْلَ لِي وَلَا قُوَّةَ",uz:"hech qanday kuch va qudratga ega emasman"}],full_uz:"Men bu yerda hech qanday kuch va qudratga ega emasman.",note:null},
{num:221,time:"00:22:32,300 --> 00:22:35,060",arabic:"لَمْ يَبْقَ مَعِي إِلَّا ثُلَّةٌ مِنَ الرِّجَالِ.",segs:[{ar:"لَمْ يَبْقَ مَعِي إِلَّا",uz:"Yonimda faqat qoldi"},{ar:"ثُلَّةٌ مِنَ الرِّجَالِ",uz:"bir guruh erkaklar"}],full_uz:"Yonimda bir guruh erkaklargina qoldi.",note:"ثُلَّةٌ — bir guruh, bir to‘da. لَمْ يَبْقَ — بَقِيَ fe’lining jazm shakli."},
{num:222,time:"00:22:35,060 --> 00:22:36,900",arabic:"يَتَحَسَّسُونَ أَعْنَاقَهُمْ.",segs:null,full_uz:"Bo‘yinlarini paypaslab turishibdi.",note:"Bu yerda bo‘ynidan ayrilishdan, ya’ni o‘ldirilishdan qo‘rqish tasvirlangan."},
{num:223,time:"00:22:36,900 --> 00:22:38,200",arabic:"وَاللَّهِ.",segs:null,full_uz:"Allohga qasam.",note:null},
{num:224,time:"00:22:38,200 --> 00:22:41,680",arabic:"وَاللَّهِ سَيَلْحَقُونَ بِجُنْدِ الْمَأْمُونِ عَاجِلًا أَمْ آجِلًا.",segs:[{ar:"وَاللَّهِ",uz:"Allohga qasam"},{ar:"سَيَلْحَقُونَ بِجُنْدِ الْمَأْمُونِ",uz:"ular Ma’munning qo‘shiniga qo‘shiladilar"},{ar:"عَاجِلًا أَمْ آجِلًا",uz:"ertami-kechmi"}],full_uz:"Allohga qasam, ular ertami-kechmi Ma’munning qo‘shiniga qo‘shiladilar.",note:"لَحِقَ بِـ — yetib bormoq, qo‘shilmoq."},
{num:225,time:"00:22:41,680 --> 00:22:45,019",arabic:"إِنْ أَلْقَى جُنُودُ طَاهِرِ بْنِ الْحُسَيْنِ الْقَبْضَ عَلَيْكَ...",segs:[{ar:"إِنْ أَلْقَى جُنُودُ طَاهِرِ بْنِ الْحُسَيْنِ",uz:"Agar Tohir ibn Husaynning askarlari"},{ar:"الْقَبْضَ عَلَيْكَ",uz:"sizni qo‘lga olsa"}],full_uz:"Agar Tohir ibn Husaynning askarlari sizni qo‘lga olsa...",note:null},
{num:226,time:"00:22:45,019 --> 00:22:47,640",arabic:"لَا يَمْنَعُهُمْ شَيْءٌ مِنْ قَتْلِكَ.",segs:[{ar:"لَا يَمْنَعُهُمْ شَيْءٌ",uz:"Ularni hech narsa to‘smaydi"},{ar:"مِنْ قَتْلِكَ",uz:"sizni o‘ldirishdan"}],full_uz:"Ularni sizni o‘ldirishdan hech narsa to‘smaydi.",note:null},
{num:227,time:"00:22:47,640 --> 00:22:52,620",arabic:"أَرَى أَنْ تَخْرُجَ تَحْتَ جُنْحِ اللَّيْلِ إِلَى الْجِهَةِ الَّتِي يُسَيْطِرُ عَلَيْهَا هَرْثَمَةُ بْنُ أَعْيَنَ.",segs:[{ar:"أَرَى أَنْ تَخْرُجَ",uz:"Chiqishingizni ma’qul ko‘raman"},{ar:"تَحْتَ جُنْحِ اللَّيْلِ",uz:"tun qorong‘iligi ostida"},{ar:"إِلَى الْجِهَةِ الَّتِي يُسَيْطِرُ عَلَيْهَا",uz:"nazorat qilinayotgan tomonga"},{ar:"هَرْثَمَةُ بْنُ أَعْيَنَ",uz:"Harsama ibn A’yan tomonidan"}],full_uz:"Tun qorong‘iligida Harsama ibn A’yan nazorat qilayotgan tomonga chiqishingizni ma’qul ko‘raman.",note:"تَحْتَ جُنْحِ اللَّيْلِ — tun qorong‘iligidan foydalanib, tun pardasi ostida."},
{num:228,time:"00:22:55,940 --> 00:22:58,980",arabic:"إِنَّهُ أَشَدُّ وَطْأَةً مِنْ طَاهِرِ بْنِ الْحُسَيْنِ.",segs:[{ar:"إِنَّهُ أَشَدُّ وَطْأَةً",uz:"U qattiqroq"},{ar:"مِنْ طَاهِرِ بْنِ الْحُسَيْنِ",uz:"Tohir ibn Husayndan"}],full_uz:"U Tohir ibn Husayndan ham qattiqqo‘lroq.",note:"أَشَدُّ وَطْأَةً — bosimi yoki zarbasi og‘irroq, qattiqroq."},
{num:229,time:"00:22:58,980 --> 00:23:02,520",arabic:"فَكِلَاهُمَا يَتَسَابَقُ لِإِظْهَارِ وَلَائِهِ لِلْمَأْمُونِ.",segs:[{ar:"فَكِلَاهُمَا يَتَسَابَقُ",uz:"Axir ikkovlari musobaqalashyapti"},{ar:"لِإِظْهَارِ وَلَائِهِ لِلْمَأْمُونِ",uz:"Ma’munga sadoqatini ko‘rsatish uchun"}],full_uz:"Axir ikkovlari Ma’munga sadoqatini ko‘rsatishda musobaqalashyapti.",note:null},
{num:230,time:"00:23:02,520 --> 00:23:06,640",arabic:"بَلْ هَرْثَمَةُ رَجُلٌ حَكِيمٌ، وَهُوَ لَنْ يُؤْذِيَكَ وَأَنْتَ أَخُو الْمَأْمُونِ.",segs:[{ar:"بَلْ هَرْثَمَةُ رَجُلٌ حَكِيمٌ",uz:"Aksincha, Harsama oqil kishi"},{ar:"وَهُوَ لَنْ يُؤْذِيَكَ",uz:"u sizga zarar yetkazmaydi"},{ar:"وَأَنْتَ أَخُو الْمَأْمُونِ",uz:"axir siz Ma’munning birodarisiz"}],full_uz:"Aksincha, Harsama oqil kishi. Siz Ma’munning birodari bo‘lganingiz uchun u sizga zarar yetkazmaydi.",note:null},
{num:231,time:"00:23:06,640 --> 00:23:09,360",arabic:"ثُمَّ إِنَّهُ كَانَ مِنْ أَشْيَاعِكَ وَأَتْبَاعِكَ.",segs:[{ar:"ثُمَّ إِنَّهُ كَانَ",uz:"Qolaversa, u bo‘lgan"},{ar:"مِنْ أَشْيَاعِكَ وَأَتْبَاعِكَ",uz:"tarafdorlaringiz va izdoshlaringizdan"}],full_uz:"Qolaversa, u tarafdorlaringiz va izdoshlaringizdan bo‘lgan.",note:"أَشْيَاعٌ — tarafdorlar; أَتْبَاعٌ — ergashuvchilar."},
{num:232,time:"00:23:09,360 --> 00:23:12,040",arabic:"كَمَا أَنَّهُ سَيَحْفَظُ لِأَبِيكَ إِكْرَامَهُ لَهُ.",segs:[{ar:"كَمَا أَنَّهُ سَيَحْفَظُ لِأَبِيكَ",uz:"U otangizning haqqini ham unutmaydi"},{ar:"إِكْرَامَهُ لَهُ",uz:"unga ko‘rsatgan hurmati uchun"}],full_uz:"U otangizning unga ko‘rsatgan hurmatini ham unutmaydi.",note:"حَفِظَ لَهُ مَعْرُوفَهُ mazmunida: birovning yaxshiligini unutmasdan qadrlash."},
{num:233,time:"00:23:12,040 --> 00:23:13,940",arabic:"كَمَا سَيَحْفَظُ لِأَخِيكَ ذَلِكَ.",segs:null,full_uz:"Birodaringizning haqqini ham shu tarzda saqlaydi.",note:null},
{num:234,time:"00:23:13,940 --> 00:23:21,940",arabic:"أَوَصَلَ بِيَ الْخِذْلَانُ إِلَى التَّشَفُّعِ بِعَدُوِّي إِلَى عَدُوِّي؟",segs:[{ar:"أَوَصَلَ بِيَ الْخِذْلَانُ",uz:"Yordamsiz qolish meni olib keldimi"},{ar:"إِلَى التَّشَفُّعِ بِعَدُوِّي",uz:"dushmanimni vositachi qilishgacha"},{ar:"إِلَى عَدُوِّي",uz:"boshqa dushmanim oldida?"}],full_uz:"Yordamsiz qolish meni bir dushmanim oldida boshqa dushmanimni vositachi qilishgacha olib keldimi?",note:"تَشَفَّعَ بِفُلَانٍ إِلَى فُلَانٍ — bir kishini boshqasi oldida o‘ziga vositachi qilmoq."},
{num:235,time:"00:23:21,940 --> 00:23:26,019",arabic:"بِئْسَتِ الدُّنْيَا.",segs:null,full_uz:"Dunyo naqadar yomon!",note:"بِئْسَ — qoralash fe’li; نِعْمَ esa maqtov fe’li."},
{num:236,time:"00:23:26,019 --> 00:23:28,960",arabic:"وَبِئْسَ مَنْ يَحْرِصُ عَلَيْهَا.",segs:[{ar:"وَبِئْسَ مَنْ",uz:"Qanday yomon kishi"},{ar:"يَحْرِصُ عَلَيْهَا",uz:"unga hirs qo‘yadigan"}],full_uz:"Unga hirs qo‘ygan kishi ham naqadar yomon!",note:"حَرَصَ عَلَى — bir narsaga qattiq intilmoq, uni qo‘ldan chiqarmaslikka urinmoq."},
{num:237,time:"00:23:35,860 --> 00:23:38,400",arabic:"الْمَأْمُونُ لَيْسَ عَدُوَّكَ يَا مُحَمَّدُ.",segs:[{ar:"الْمَأْمُونُ لَيْسَ عَدُوَّكَ",uz:"Ma’mun dushmaningiz emas"},{ar:"يَا مُحَمَّدُ",uz:"ey Muhammad"}],full_uz:"Ma’mun dushmaningiz emas, Muhammad.",note:null},
{num:238,time:"00:23:38,400 --> 00:23:40,759",arabic:"إِنَّهُ أَخُوكَ.",segs:null,full_uz:"Axir u birodaringiz.",note:null},
{num:239,time:"00:23:40,759 --> 00:23:45,259",arabic:"وَلَوْلَا الْوُشَاةُ وَالْمُغْرِضُونَ الَّذِينَ فَرَّقُوا بَيْنَكُمْ...",segs:[{ar:"وَلَوْلَا الْوُشَاةُ وَالْمُغْرِضُونَ",uz:"Agar chaqimchilar va g‘arazli kishilar bo‘lmaganida"},{ar:"الَّذِينَ فَرَّقُوا بَيْنَكُمْ",uz:"sizlarning orangizni ajratgan"}],full_uz:"Orangizni ajratgan chaqimchilar va g‘arazli kishilar bo‘lmaganida...",note:"وُشَاةٌ — وَاشٍ («chaqimchi») so‘zining ko‘pligi; مُغْرِضٌ — yashirin yomon maqsadi bor kishi."},
{num:240,time:"00:23:45,259 --> 00:23:48,900",arabic:"لَمَا وَصَلَتِ الْحَالُ إِلَى مَا وَصَلَتْ إِلَيْهِ الْآنَ.",segs:[{ar:"لَمَا وَصَلَتِ الْحَالُ",uz:"ahvol yetib kelmagan bo‘lardi"},{ar:"إِلَى مَا وَصَلَتْ إِلَيْهِ الْآنَ",uz:"hozirgi darajasiga"}],full_uz:"Ahvol hozirgi darajasiga yetib kelmagan bo‘lardi.",note:null},
{num:241,time:"00:23:48,900 --> 00:23:53,940",arabic:"يَبْدُو أَنَّنِي تَمَادَيْتُ فِي خَطَئِي.",segs:[{ar:"يَبْدُو أَنَّنِي",uz:"Aftidan, men"},{ar:"تَمَادَيْتُ فِي خَطَئِي",uz:"xatoyimda haddan oshib ketdim"}],full_uz:"Aftidan, xatoyimda haddan oshib ketdim.",note:"تَمَادَى فِي — bir ishda to‘xtamay davom etib, haddan oshmoq."},
{num:242,time:"00:23:53,940 --> 00:23:57,379",arabic:"إِلَى الْحَدِّ الَّذِي أَسْتَحِقُّ عَلَيْهِ مَا يَجْرِي.",segs:[{ar:"إِلَى الْحَدِّ الَّذِي",uz:"Shunday darajagachaki"},{ar:"أَسْتَحِقُّ عَلَيْهِ مَا يَجْرِي",uz:"uning uchun sodir bo‘layotgan narsalarga loyiqman"}],full_uz:"Shu darajagachaki, sodir bo‘layotgan narsalarga loyiq bo‘lib qoldim.",note:null},
{num:243,time:"00:24:40,759 --> 00:24:43,119",arabic:"مُوسَى وَعَبْدُ اللَّهِ أَمَانَةٌ لَدَيْكِ يَا أُمَّاهُ.",segs:[{ar:"مُوسَى وَعَبْدُ اللَّهِ",uz:"Muso va Abdulloh"},{ar:"أَمَانَةٌ لَدَيْكِ",uz:"sizga omonat"},{ar:"يَا أُمَّاهُ",uz:"onajon"}],full_uz:"Muso va Abdulloh sizga omonat, onajon.",note:"أَمَانَةٌ لَدَيْكِ — sizning ishonchli himoyangizga topshirilgan omonat."},
{num:244,time:"00:24:47,079 --> 00:24:48,519",arabic:"السَّلَامُ عَلَيْكُمْ.",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:245,time:"00:24:48,519 --> 00:24:50,700",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"Sizlarga ham tinchlik bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",uz:"va Allohning rahmati hamda barakalari"}],full_uz:"Sizlarga ham tinchlik, Allohning rahmati va barakalari bo‘lsin.",note:null},
{num:246,time:"00:24:50,700 --> 00:24:53,640",arabic:"نَحْنُ جَاهِزُونَ لِلْخُرُوجِ إِلَى هَرْثَمَةَ يَا أَبَا مُوسَى.",segs:[{ar:"نَحْنُ جَاهِزُونَ",uz:"Biz tayyormiz"},{ar:"لِلْخُرُوجِ إِلَى هَرْثَمَةَ",uz:"Harsamaning oldiga yo‘lga chiqishga"},{ar:"يَا أَبَا مُوسَى",uz:"ey Abu Muso"}],full_uz:"Biz Harsamaning oldiga yo‘lga chiqishga tayyormiz, ey Abu Muso.",note:null},
{num:247,time:"00:24:53,640 --> 00:24:56,220",arabic:"إِنَّهُ يَنْتَظِرُكَ عَلَى شَاطِئِ دِجْلَةَ.",segs:[{ar:"إِنَّهُ يَنْتَظِرُكَ",uz:"U sizni kutyapti"},{ar:"عَلَى شَاطِئِ دِجْلَةَ",uz:"Dajla qirg‘og‘ida"}],full_uz:"U sizni Dajla qirg‘og‘ida kutyapti.",note:null},
{num:248,time:"00:27:10,759 --> 00:27:21,000",arabic:"مَنْ، مَنْ ذَا أَصَابَكِ يَا بَغْدَادُ بِالْعَيْنِ؟",segs:[{ar:"مَنْ، مَنْ ذَا أَصَابَكِ",uz:"Kim, kim senga tekkizdi"},{ar:"يَا بَغْدَادُ",uz:"ey Bag‘dod"},{ar:"بِالْعَيْنِ",uz:"ko‘zini?"}],full_uz:"Kim, kimning ko‘zi tegdi senga, ey Bag‘dod?",note:"أَصَابَهُ بِالْعَيْنِ — «unga ko‘zi tegdi»."},
{num:249,time:"00:27:21,000 --> 00:27:25,140",arabic:"أَلَمْ تَكُونِي زَمَانًا قُرَّةَ الْعَيْنِ؟",segs:[{ar:"أَلَمْ تَكُونِي زَمَانًا",uz:"Bir zamonlar emasmiding"},{ar:"قُرَّةَ الْعَيْنِ",uz:"ko‘z quvonchi?"}],full_uz:"Bir zamonlar ko‘z quvonchi emasmiding?",note:"قُرَّةُ الْعَيْنِ — ko‘z quvonchi, dilga taskin beradigan narsa yoki kishi."},
{num:250,time:"00:28:07,839 --> 00:28:11,480",arabic:"أَلَمْ تَكُونِي يَوْمًا قُرَّةَ الْعَيْنِ؟",segs:[{ar:"أَلَمْ تَكُونِي يَوْمًا",uz:"Bir paytlar emasmiding"},{ar:"قُرَّةَ الْعَيْنِ",uz:"ko‘z quvonchi?"}],full_uz:"Bir paytlar ko‘z quvonchi emasmiding?",note:null},
{num:251,time:"00:29:37,839 --> 00:29:41,279",arabic:"لَكِنِّي عَلَى يَقِينٍ مِنْ ذَلِكَ.",segs:[{ar:"لَكِنِّي عَلَى يَقِينٍ",uz:"Ammo men qat’iy aminman"},{ar:"مِنْ ذَلِكَ",uz:"bundan"}],full_uz:"Ammo men bunga qat’iy aminman.",note:"عَلَى يَقِينٍ مِنْ — bir narsaga to‘liq ishonch hosil qilgan."},
{num:252,time:"00:29:41,279 --> 00:29:44,899",arabic:"الْأَخُ لَا يَقْتُلُ ابْنَ أَبِيهِ.",segs:[{ar:"الْأَخُ لَا يَقْتُلُ",uz:"Birodar o‘ldirmaydi"},{ar:"ابْنَ أَبِيهِ",uz:"o‘z otasining o‘g‘lini"}],full_uz:"Birodar o‘z otasining o‘g‘lini o‘ldirmaydi.",note:"ابْنُ أَبِيهِ — «otasining o‘g‘li», ya’ni birodari."},
{num:253,time:"00:29:44,899 --> 00:29:50,359",arabic:"الْمَأْمُونُ أَعْقَلُ مِنْ ذَلِكَ بِكَثِيرٍ.",segs:[{ar:"الْمَأْمُونُ أَعْقَلُ مِنْ ذَلِكَ",uz:"Ma’mun bunday qilishdan aqlliroq"},{ar:"بِكَثِيرٍ",uz:"ancha"}],full_uz:"Ma’mun bunday ish qilmaydigan darajada ancha aqlli.",note:"أَعْقَلُ مِنْ ذَلِكَ — «bunday ish qilishdan ko‘ra aqlliroq», ya’ni bunga aqli yo‘l qo‘ymaydi."},
{num:254,time:"00:29:50,359 --> 00:29:54,839",arabic:"الدِّينُ وَالدَّمُ يَأْبَيَانِ ذَلِكَ.",segs:[{ar:"الدِّينُ وَالدَّمُ",uz:"Din va qon qarindoshligi"},{ar:"يَأْبَيَانِ ذَلِكَ",uz:"bunga yo‘l qo‘ymaydi"}],full_uz:"Din va qon qarindoshligi bunga yo‘l qo‘ymaydi.",note:"يَأْبَيَانِ — ikkilik shakli: «ikkalasi rad etadi». أَبَى — يَأْبَى."},
{num:255,time:"00:30:07,839 --> 00:30:14,299",arabic:"كَمْ جَرَيَا فِي هَذَا الْمَكَانِ عِنْدَمَا كَانَا صَغِيرَيْنِ!",segs:[{ar:"كَمْ جَرَيَا فِي هَذَا الْمَكَانِ",uz:"Bu joyda qanchalar yugurishgan"},{ar:"عِنْدَمَا كَانَا صَغِيرَيْنِ",uz:"ikkovlari kichkina bo‘lganida!"}],full_uz:"Ikkovlari kichkina bo‘lganida bu joyda qanchalar yugurishgan!",note:"جَرَيَا va كَانَا — ikki kishiga tegishli shakllar. كَمْ bu yerda ko‘plik va xotirlashni ifodalaydi."},
{num:256,time:"00:30:14,299 --> 00:30:21,000",arabic:"كَمْ تَسَامَرَا وَتَنَاقَشَا!",segs:[{ar:"كَمْ تَسَامَرَا",uz:"Qanchalar kechki suhbatlar qilishgan"},{ar:"وَتَنَاقَشَا",uz:"va fikr almashishgan!"}],full_uz:"Qanchalar kechki suhbatlar qilib, fikr almashishgan!",note:"تَسَامَرَ — kechasi suhbat qurmoq. Ikkala fe’l ham ikkilik shaklida."},
{num:257,time:"00:30:21,000 --> 00:30:23,879",arabic:"وَرُبَّمَا تَشَاجَرَا.",segs:null,full_uz:"Ba’zan janjallashib ham qolishgan.",note:"تَشَاجَرَا — «ikkovlari janjallashdilar»."},
{num:258,time:"00:30:23,879 --> 00:30:28,279",arabic:"لَكِنَّهُمَا لَمْ يَتَقَاتَلَا.",segs:null,full_uz:"Ammo ikkovlari bir-biriga qarshi jang qilishmagan.",note:"يَتَقَاتَلَا — ikkilik shakli; لَمْ sababli oxiridagi ن tushgan."},
{num:259,time:"00:30:29,599 --> 00:30:33,119",arabic:"لَمْ يَتَقَاتَلَا.",segs:null,full_uz:"Ikkovlari bir-biriga qarshi jang qilishmagan.",note:null},
{num:260,time:"00:30:37,739 --> 00:30:51,379",arabic:"غَدًا سَيَلْتَقِي الْأَمِينُ...",segs:null,full_uz:"Ertaga Amin uchrashadi...",note:null},
{num:261,time:"00:30:51,379 --> 00:30:53,119",arabic:"أَمِيرُ الْمُؤْمِنِينَ...",segs:null,full_uz:"Mo‘minlar amiri...",note:null},
{num:262,time:"00:30:53,119 --> 00:30:55,159",arabic:"بِوَلِيِّ عَهْدِهِ الْمَأْمُونِ.",segs:null,full_uz:"O‘z valiahdi Ma’mun bilan.",note:"اِلْتَقَى بِفُلَانٍ — birov bilan uchrashmoq."},
{num:263,time:"00:30:55,159 --> 00:30:58,379",arabic:"وَسَيَنْتَهِي كُلُّ شَيْءٍ.",segs:null,full_uz:"Va hamma narsa tugaydi.",note:null},
{num:264,time:"00:30:58,819 --> 00:31:01,879",arabic:"أَنَا عَلَى يَقِينٍ مِنْ ذَلِكَ.",segs:null,full_uz:"Men bunga qat’iy aminman.",note:null},
{num:265,time:"00:31:15,360 --> 00:31:17,920",arabic:"هَذِهِ نِهَايَةُ الطَّاغِيَةِ.",segs:null,full_uz:"Bu zolimning oxiri.",note:null},
{num:266,time:"00:31:17,920 --> 00:31:19,040",arabic:"الْحَمْدُ لِلَّهِ.",segs:null,full_uz:"Allohga hamd bo‘lsin.",note:null},
{num:267,time:"00:31:19,040 --> 00:31:23,560",arabic:"الْحَمْدُ لِلَّهِ الَّذِي أَرَاحَنَا مِنْ فِرْعَوْنَ آخَرَ.",segs:[{ar:"الْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"الَّذِي أَرَاحَنَا",uz:"bizni qutqargan"},{ar:"مِنْ فِرْعَوْنَ آخَرَ",uz:"yana bir Fir’avndan"}],full_uz:"Bizni yana bir Fir’avndan qutqargan Allohga hamd bo‘lsin.",note:"أَرَاحَهُ مِنْ — uni biror tashvish yoki mashaqqatdan xalos qilmoq."},
{num:268,time:"00:31:23,560 --> 00:31:27,060",arabic:"نَرْجُو أَنْ يُتِمَّ اللَّهُ الْأُمُورَ عَلَى خَيْرٍ.",segs:[{ar:"نَرْجُو أَنْ يُتِمَّ اللَّهُ الْأُمُورَ",uz:"Alloh ishlarni yakunlashini umid qilamiz"},{ar:"عَلَى خَيْرٍ",uz:"yaxshilik bilan"}],full_uz:"Alloh ishlarni yaxshilik bilan yakunlashini umid qilamiz.",note:null},
{num:269,time:"00:31:27,060 --> 00:31:29,600",arabic:"وَتَجْرِيَ كَمَا نَظُنُّ وَنَحْسَبُ.",segs:[{ar:"وَتَجْرِيَ",uz:"Va kechishini"},{ar:"كَمَا نَظُنُّ وَنَحْسَبُ",uz:"biz o‘ylagan va hisoblagandek"}],full_uz:"Va ishlar biz o‘ylagandek kechishini.",note:null},
{num:270,time:"00:31:29,599 --> 00:31:33,240",arabic:"لَمْ يَبْقَ لَهُ شَيْءٌ فِي بَغْدَادَ يَا أَبَا مَعْنٍ.",segs:[{ar:"لَمْ يَبْقَ لَهُ شَيْءٌ",uz:"Uning hech narsasi qolmadi"},{ar:"فِي بَغْدَادَ",uz:"Bag‘dodda"},{ar:"يَا أَبَا مَعْنٍ",uz:"ey Abu Ma’n"}],full_uz:"Uning Bag‘dodda hech narsasi qolmadi, ey Abu Ma’n.",note:null},
{num:271,time:"00:31:33,240 --> 00:31:36,679",arabic:"هَرَبَ جُنْدُهُ وَوُزَرَاؤُهُ.",segs:null,full_uz:"Uning askarlari va vazirlari qochib ketdi.",note:null},
{num:272,time:"00:31:36,679 --> 00:31:39,599",arabic:"وَقَدْ هَرَبَ هُوَ أَيْضًا.",segs:null,full_uz:"O‘zi ham qochib ketdi.",note:null},
{num:273,time:"00:31:39,599 --> 00:31:43,159",arabic:"فِي الْحُرُوبِ تَكْثُرُ الْأَقَاوِيلُ وَتَنْتَشِرُ الشَّائِعَاتُ.",segs:[{ar:"فِي الْحُرُوبِ",uz:"Urushlarda"},{ar:"تَكْثُرُ الْأَقَاوِيلُ",uz:"gap-so‘zlar ko‘payadi"},{ar:"وَتَنْتَشِرُ الشَّائِعَاتُ",uz:"va mish-mishlar tarqaladi"}],full_uz:"Urushlarda gap-so‘zlar ko‘payib, mish-mishlar tarqaladi.",note:"شَائِعَةٌ — mish-mish; ko‘pligi شَائِعَاتٌ."},
{num:274,time:"00:31:43,159 --> 00:31:45,719",arabic:"وَلَا أُصَدِّقُ حَتَّى أَرَى بِعَيْنِي.",segs:[{ar:"وَلَا أُصَدِّقُ",uz:"Men ishonmayman"},{ar:"حَتَّى أَرَى بِعَيْنِي",uz:"o‘z ko‘zim bilan ko‘rmagunimcha"}],full_uz:"O‘z ko‘zim bilan ko‘rmagunimcha ishonmayman.",note:null},
{num:275,time:"00:31:45,719 --> 00:31:48,500",arabic:"سَتَرَى بِعَيْنَيْكَ يَا بَدْرُ مَا يَسُرُّكَ.",segs:[{ar:"سَتَرَى بِعَيْنَيْكَ يَا بَدْرُ",uz:"O‘z ko‘zlaringiz bilan ko‘rasiz, Badr"},{ar:"مَا يَسُرُّكَ",uz:"sizni xursand qiladigan narsani"}],full_uz:"Sizni xursand qiladigan narsani o‘z ko‘zlaringiz bilan ko‘rasiz, Badr.",note:null},
{num:276,time:"00:31:48,500 --> 00:31:52,779",arabic:"الْحَمْدُ لِلَّهِ الَّذِي أَخْلَفَ صَبْرَنَا نَصْرًا.",segs:[{ar:"الْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"الَّذِي أَخْلَفَ صَبْرَنَا نَصْرًا",uz:"sabrimiz ortidan g‘alaba bergan"}],full_uz:"Sabrimiz ortidan g‘alaba bergan Allohga hamd bo‘lsin.",note:null},
{num:277,time:"00:31:52,779 --> 00:31:55,039",arabic:"وَضِيقَنَا فَرَجًا.",segs:null,full_uz:"Va tangligimiz ortidan yengillik bergan.",note:"فَرَجٌ — qiyinchilikdan keyingi yengillik, najot."},
{num:278,time:"00:31:56,099 --> 00:31:59,339",arabic:"ظَهَرَ الْحَقُّ وَزَهَقَ الْبَاطِلُ.",segs:[{ar:"ظَهَرَ الْحَقُّ",uz:"Haq yuzaga chiqdi"},{ar:"وَزَهَقَ الْبَاطِلُ",uz:"va botil yo‘q bo‘ldi"}],full_uz:"Haq yuzaga chiqdi va botil yo‘q bo‘ldi.",note:"زَهَقَ — yo‘q bo‘lmoq, barham topmoq."},
{num:279,time:"00:31:59,339 --> 00:32:05,399",arabic:"قَرِيبًا سَتَكْتَحِلُ عُيُونُكُمْ بِرُؤْيَةِ أَمِيرِ الْمُؤْمِنِينَ الْمَأْمُونِ.",segs:[{ar:"قَرِيبًا سَتَكْتَحِلُ عُيُونُكُمْ",uz:"Yaqinda ko‘zlaringiz quvonadi"},{ar:"بِرُؤْيَةِ أَمِيرِ الْمُؤْمِنِينَ الْمَأْمُونِ",uz:"mo‘minlar amiri Ma’munni ko‘rish bilan"}],full_uz:"Yaqinda mo‘minlar amiri Ma’munni ko‘rib, ko‘zlaringiz quvonadi.",note:"اِكْتَحَلَتْ عَيْنُهُ بِرُؤْيَتِهِ — so‘zma-so‘z uning ko‘rinishi ko‘zga surma bo‘lishi; ko‘rib quvonish timsoli."},
{num:280,time:"00:32:05,399 --> 00:32:08,799",arabic:"حَمَاهُ اللَّهُ وَحَفِظَهُ مِنْ كُلِّ شَرٍّ.",segs:[{ar:"حَمَاهُ اللَّهُ وَحَفِظَهُ",uz:"Alloh uni himoya qilib, asrasin"},{ar:"مِنْ كُلِّ شَرٍّ",uz:"har qanday yomonlikdan"}],full_uz:"Alloh uni himoya qilib, har qanday yomonlikdan asrasin.",note:null},
{num:281,time:"00:32:08,799 --> 00:32:11,319",arabic:"النَّصْرُ لِأَمِيرِ الْمُؤْمِنِينَ الْمَأْمُونِ!",segs:null,full_uz:"G‘alaba mo‘minlar amiri Ma’munga!",note:null},
{num:282,time:"00:32:11,319 --> 00:32:13,419",arabic:"النَّصْرُ لِأَمِيرِ الْمُؤْمِنِينَ!",segs:null,full_uz:"G‘alaba mo‘minlar amiriga!",note:null},
{num:283,time:"00:32:13,419 --> 00:32:26,539",arabic:"أَيُعْقَلُ أَنْ تَكُونَ هَذِهِ النِّهَايَةُ؟",segs:[{ar:"أَيُعْقَلُ",uz:"Aqlga sig‘adimi"},{ar:"أَنْ تَكُونَ هَذِهِ النِّهَايَةُ",uz:"oxiri shu bo‘lishi?"}],full_uz:"Oxiri shu bo‘lishi aqlga sig‘adimi?",note:null},
{num:284,time:"00:32:26,539 --> 00:32:41,859",arabic:"مَوْلَايَ أَمِيرَ الْمُؤْمِنِينَ!",segs:null,full_uz:"Hazratim, mo‘minlar amiri!",note:null},
{num:285,time:"00:32:41,859 --> 00:32:44,779",arabic:"كَيْفَ أَمْسَكَ بِكَ هَؤُلَاءِ الْأَوْغَادُ؟",segs:[{ar:"كَيْفَ أَمْسَكَ بِكَ",uz:"Sizni qanday tutib oldi"},{ar:"هَؤُلَاءِ الْأَوْغَادُ",uz:"bu razillar?"}],full_uz:"Bu razillar sizni qanday tutib oldi?",note:"أَوْغَادٌ — وَغْدٌ («razil, pastkash») so‘zining ko‘pligi."},
{num:286,time:"00:32:52,000 --> 00:32:54,460",arabic:"لَقَدْ هَاجَمَنَا جُنْدُ طَاهِرِ بْنِ الْحُسَيْنِ.",segs:[{ar:"لَقَدْ هَاجَمَنَا",uz:"Bizga hujum qildi"},{ar:"جُنْدُ طَاهِرِ بْنِ الْحُسَيْنِ",uz:"Tohir ibn Husaynning askarlari"}],full_uz:"Bizga Tohir ibn Husaynning askarlari hujum qildi.",note:null},
{num:287,time:"00:32:54,460 --> 00:32:57,180",arabic:"فَأَغْرَقُونَا فِي الْمَاءِ جَمِيعًا.",segs:[{ar:"فَأَغْرَقُونَا فِي الْمَاءِ",uz:"Bizni suvga g‘arq qildilar"},{ar:"جَمِيعًا",uz:"hammamizni"}],full_uz:"Hammamizni suvga g‘arq qildilar.",note:null},
{num:288,time:"00:32:57,180 --> 00:32:59,759",arabic:"فَخَرَجْتُ سِبَاحَةً إِلَى الشَّاطِئِ.",segs:[{ar:"فَخَرَجْتُ سِبَاحَةً",uz:"Shunda suzib chiqdim"},{ar:"إِلَى الشَّاطِئِ",uz:"qirg‘oqqa"}],full_uz:"Shunda qirg‘oqqa suzib chiqdim.",note:null},
{num:289,time:"00:32:59,759 --> 00:33:01,960",arabic:"أَمْسَكَ بِي هَؤُلَاءِ.",segs:null,full_uz:"Bular meni tutib oldi.",note:null},
{num:290,time:"00:33:01,960 --> 00:33:03,460",arabic:"ثُمَّ...",segs:null,full_uz:"So‘ng...",note:null},
{num:291,time:"00:33:03,460 --> 00:33:05,779",arabic:"فِدَاكَ نَفْسِي يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"فِدَاكَ نَفْسِي",uz:"Jonim sizga fido bo‘lsin"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Jonim sizga fido bo‘lsin, ey mo‘minlar amiri.",note:null},
{num:292,time:"00:33:05,779 --> 00:33:08,440",arabic:"كَيْفَ يَجْرُؤُونَ عَلَى فِعْلِ ذَلِكَ بِكَ؟",segs:[{ar:"كَيْفَ يَجْرُؤُونَ",uz:"Qanday jur’at qilishadi"},{ar:"عَلَى فِعْلِ ذَلِكَ بِكَ",uz:"sizga bunday qilishga?"}],full_uz:"Sizga bunday qilishga qanday jur’at qilishadi?",note:null},
{num:293,time:"00:33:08,440 --> 00:33:10,980",arabic:"وَأَنْتَ ابْنُ الرَّشِيدِ وَأَخُو الْمَأْمُونِ.",segs:[{ar:"وَأَنْتَ ابْنُ الرَّشِيدِ",uz:"Axir siz Rashidning o‘g‘lisiz"},{ar:"وَأَخُو الْمَأْمُونِ",uz:"va Ma’munning birodarisiz"}],full_uz:"Axir siz Rashidning o‘g‘li va Ma’munning birodarisiz.",note:null},
{num:294,time:"00:33:10,980 --> 00:33:13,240",arabic:"الْوُجُوهُ الَّتِي رَأَيْتُهَا...",segs:null,full_uz:"Men ko‘rgan yuzlar...",note:null},
{num:295,time:"00:33:13,240 --> 00:33:15,900",arabic:"لَا تَعْرِفُ إِلَّا الدَّمَ وَالْمَالَ.",segs:null,full_uz:"Faqat qon va pulni biladi.",note:null},
{num:296,time:"00:33:15,900 --> 00:33:19,500",arabic:"وَلَا تَحْسِبُ حِسَابًا حَتَّى لِلْمَأْمُونِ ذَاتِهِ.",segs:[{ar:"وَلَا تَحْسِبُ حِسَابًا",uz:"Va hisoblashmaydi"},{ar:"حَتَّى لِلْمَأْمُونِ ذَاتِهِ",uz:"hatto Ma’munning o‘zi bilan ham"}],full_uz:"Hatto Ma’munning o‘zi bilan ham hisoblashmaydi.",note:"حَسَبَ حِسَابًا لِفُلَانٍ — birovni hisobga olmoq, u bilan hisoblashmoq."},
{num:297,time:"00:33:19,500 --> 00:33:21,920",arabic:"فَإِنَّ حِقْدَهُمْ هُوَ الَّذِي يُسَيِّرُهُمْ.",segs:[{ar:"فَإِنَّ حِقْدَهُمْ",uz:"Chunki ularning kini"},{ar:"هُوَ الَّذِي يُسَيِّرُهُمْ",uz:"ularni boshqaryapti"}],full_uz:"Chunki ularni o‘zlarining kini boshqaryapti.",note:"سَيَّرَ bu yerda «boshqarmoq, harakatga undamoq»."},
{num:298,time:"00:33:21,920 --> 00:33:23,380",arabic:"لَا طَاعَةُ الْمَأْمُونِ.",segs:null,full_uz:"Ma’munga itoat emas.",note:null},
{num:299,time:"00:33:23,380 --> 00:33:25,560",arabic:"لَنْ يَجْرُؤُوا عَلَى الْإِسَاءَةِ إِلَيْكَ.",segs:[{ar:"لَنْ يَجْرُؤُوا",uz:"Ular jur’at qilolmaydilar"},{ar:"عَلَى الْإِسَاءَةِ إِلَيْكَ",uz:"sizga yomonlik qilishga"}],full_uz:"Ular sizga yomonlik qilishga jur’at qilolmaydilar.",note:null},
{num:300,time:"00:33:25,560 --> 00:33:27,520",arabic:"إِنَّهُمْ أَهْوَنُ مِنْ ذَلِكَ.",segs:null,full_uz:"Ular bunday qilishga ojizlik qiladilar.",note:"أَهْوَنُ مِنْ ذَلِكَ — bunga kuchi yetmaydigan darajada ojiz yoki arzimas."},
{num:301,time:"00:33:27,520 --> 00:33:31,380",arabic:"أَتَظُنُّ ذَلِكَ أَيُّهَا الْحَارِثُ؟",segs:[{ar:"أَتَظُنُّ ذَلِكَ",uz:"Shunday deb o‘ylaysizmi"},{ar:"أَيُّهَا الْحَارِثُ",uz:"ey Horis?"}],full_uz:"Shunday deb o‘ylaysizmi, ey Horis?",note:null},
{num:302,time:"00:33:34,100 --> 00:33:36,240",arabic:"أَنَا عَلَى يَقِينٍ مِنْ ذَلِكَ يَا مَوْلَايَ.",segs:[{ar:"أَنَا عَلَى يَقِينٍ مِنْ ذَلِكَ",uz:"Men bunga qat’iy aminman"},{ar:"يَا مَوْلَايَ",uz:"hazratim"}],full_uz:"Men bunga qat’iy aminman, hazratim.",note:null},
{num:303,time:"00:33:36,240 --> 00:33:37,900",arabic:"غَايَةُ مَا فِي الْأَمْرِ...",segs:null,full_uz:"Bor gap shuki...",note:"غَايَةُ مَا فِي الْأَمْرِ — masalaning bor-yo‘g‘i, eng ko‘pi bilan bo‘ladigan narsa."},
{num:304,time:"00:33:37,900 --> 00:33:40,540",arabic:"أَنَّهُمْ سَيُرْسِلُونَكَ إِلَى الْأَمِيرِ الْمَأْمُونِ.",segs:[{ar:"أَنَّهُمْ سَيُرْسِلُونَكَ",uz:"ular sizni yuboradilar"},{ar:"إِلَى الْأَمِيرِ الْمَأْمُونِ",uz:"amir Ma’munning oldiga"}],full_uz:"Ular sizni amir Ma’munning oldiga yuboradilar.",note:null},
{num:305,time:"00:33:40,540 --> 00:33:43,380",arabic:"تَتَّفِقَانِ عَلَى صِيغَةِ تَفَاهُمٍ فِيمَا بَيْنَكُمَا.",segs:[{ar:"تَتَّفِقَانِ",uz:"Ikkovingiz kelishasiz"},{ar:"عَلَى صِيغَةِ تَفَاهُمٍ",uz:"bir murosa shakli ustida"},{ar:"فِيمَا بَيْنَكُمَا",uz:"o‘zaro"}],full_uz:"Ikkovingiz o‘zaro bir murosaga kelasiz.",note:"تَتَّفِقَانِ — ikki kishiga qaratilgan shakl."},
{num:306,time:"00:33:44,060 --> 00:33:47,440",arabic:"أَعْلَمُ أَنِّي أَخْطَأْتُ.",segs:null,full_uz:"Xato qilganimni bilaman.",note:null},
{num:307,time:"00:33:47,440 --> 00:33:50,720",arabic:"وَلَكِنَّ خَطَأَ الْمَأْمُونِ كَانَ أَفْدَحَ.",segs:[{ar:"وَلَكِنَّ خَطَأَ الْمَأْمُونِ",uz:"Ammo Ma’munning xatosi"},{ar:"كَانَ أَفْدَحَ",uz:"og‘irroq edi"}],full_uz:"Ammo Ma’munning xatosi og‘irroq edi.",note:"أَفْدَحُ — oqibati og‘irroq, dahshatliroq."},
{num:308,time:"00:33:50,720 --> 00:33:54,680",arabic:"فَهُوَ لَمْ يَعِ مَا فَعَلَهُ.",segs:[{ar:"فَهُوَ لَمْ يَعِ",uz:"Chunki u anglamadi"},{ar:"مَا فَعَلَهُ",uz:"nima qilganini"}],full_uz:"Chunki u nima qilganini anglamadi.",note:"وَعَى — يَعِي — لَمْ يَعِ: «angladi — anglaydi — anglamadi»."},
{num:309,time:"00:33:54,680 --> 00:33:58,720",arabic:"أَسْلَمْنَا أَنْفُسَنَا إِلَى هَؤُلَاءِ الْحَاقِدِينَ.",segs:[{ar:"أَسْلَمْنَا أَنْفُسَنَا",uz:"O‘zimizni topshirdik"},{ar:"إِلَى هَؤُلَاءِ الْحَاقِدِينَ",uz:"bu kinli kishilarga"}],full_uz:"O‘zimizni bu kinli kishilarga topshirdik.",note:null},
{num:310,time:"00:33:58,720 --> 00:34:02,620",arabic:"حَتَّى نَالَ كُلٌّ مِنَّا جَزَاءَ مَا فَعَلَهُ.",segs:[{ar:"حَتَّى نَالَ كُلٌّ مِنَّا",uz:"Oxiri har birimiz oldik"},{ar:"جَزَاءَ مَا فَعَلَهُ",uz:"qilgan ishimizning jazosini"}],full_uz:"Oxiri har birimiz qilgan ishimizning jazosini oldik.",note:null},
{num:311,time:"00:34:02,620 --> 00:34:06,579",arabic:"نَحْنُ فَعَلْنَا هَذَا.",segs:null,full_uz:"Buni o‘zimiz qildik.",note:null},
{num:312,time:"00:34:06,579 --> 00:34:09,179",arabic:"نَحْنُ أَيُّهَا الْحَارِثُ.",segs:null,full_uz:"O‘zimiz, ey Horis.",note:null},
{num:313,time:"00:34:20,719 --> 00:34:33,279",arabic:"يَبْدُو أَنَّ مَا يَجْرِي حَوْلَنَا قَدْ نَالَ مِنْ عَزِيمَتِكِ يَا أُمَّ أَحْمَدَ.",segs:[{ar:"يَبْدُو أَنَّ مَا يَجْرِي حَوْلَنَا",uz:"Aftidan, atrofimizdagi voqealar"},{ar:"قَدْ نَالَ مِنْ عَزِيمَتِكِ",uz:"qat’iyatingizni susaytiribdi"},{ar:"يَا أُمَّ أَحْمَدَ",uz:"ey Ummu Ahmad"}],full_uz:"Aftidan, atrofimizdagi voqealar qat’iyatingizni susaytiribdi, ey Ummu Ahmad.",note:"نَالَ مِنْ عَزِيمَتِهِ — uning qat’iyatiga putur yetkazmoq."},
{num:314,time:"00:34:33,279 --> 00:34:37,059",arabic:"لَا اعْتِرَاضَ عَلَى قَدَرِ اللَّهِ يَا وَلَدِي.",segs:[{ar:"لَا اعْتِرَاضَ عَلَى قَدَرِ اللَّهِ",uz:"Allohning taqdiriga e’tiroz yo‘q"},{ar:"يَا وَلَدِي",uz:"bolam"}],full_uz:"Allohning taqdiriga e’tiroz yo‘q, bolam.",note:null},
{num:315,time:"00:34:37,059 --> 00:34:42,719",arabic:"أَنْتَ تَظُنُّ أَنَّ أُمَّكَ خَائِفَةٌ، أَلَيْسَ كَذَلِكَ؟",segs:[{ar:"أَنْتَ تَظُنُّ أَنَّ أُمَّكَ خَائِفَةٌ",uz:"Onangiz qo‘rqyapti deb o‘ylayapsiz"},{ar:"أَلَيْسَ كَذَلِكَ",uz:"shunday emasmi?"}],full_uz:"Onangiz qo‘rqyapti deb o‘ylayapsiz, shunday emasmi?",note:null},
{num:316,time:"00:34:42,719 --> 00:34:44,719",arabic:"لَقَدْ عَرَكَتْنَا الْأَيَّامُ يَا وَلَدِي.",segs:null,full_uz:"Kunlar bizni chiniqtirgan, bolam.",note:"عَرَكَتْهُ الْأَيَّامُ — hayot sinovlari uni chiniqtirdi."},
{num:317,time:"00:34:44,719 --> 00:34:49,119",arabic:"وَرَأَيْنَا مِنْ أَهْوَالِهَا مَا تَشِيبُ لَهُ الْوِلْدَانُ.",segs:[{ar:"وَرَأَيْنَا مِنْ أَهْوَالِهَا",uz:"Uning dahshatlaridan ko‘rdik"},{ar:"مَا تَشِيبُ لَهُ الْوِلْدَانُ",uz:"bolalarning sochini oqartiradiganlarini"}],full_uz:"Uning bolalarning ham sochini oqartiradigan dahshatlarini ko‘rdik.",note:"تَشِيبُ لَهُ الْوِلْدَانُ — dahshatning kattaligini ifodalovchi mubolag‘a."},
{num:318,time:"00:34:49,119 --> 00:34:55,659",arabic:"وَمَعَ ذَلِكَ فَقَدْ ثَبَّتَنَا اللَّهُ وَلَمْ نَهِنْ وَلَمْ نَفِرَّ.",segs:[{ar:"وَمَعَ ذَلِكَ",uz:"Shunga qaramay"},{ar:"فَقَدْ ثَبَّتَنَا اللَّهُ",uz:"Alloh bizni sobit qildi"},{ar:"وَلَمْ نَهِنْ",uz:"zaiflashmadik"},{ar:"وَلَمْ نَفِرَّ",uz:"va qochmadik"}],full_uz:"Shunga qaramay, Alloh bizni sobit qildi, zaiflashmadik va qochmadik.",note:"وَهَنَ — يَهِنُ: «zaiflashmoq»; لَمْ نَهِنْ — «biz zaiflashmadik»."},
{num:319,time:"00:34:55,659 --> 00:34:59,599",arabic:"لَكِنَّ الدِّمَاءَ تَجْرِفُ فِي طَرِيقِهَا الْآمَالَ.",segs:[{ar:"لَكِنَّ الدِّمَاءَ تَجْرِفُ",uz:"Ammo qonlar oqizib ketadi"},{ar:"فِي طَرِيقِهَا الْآمَالَ",uz:"yo‘lidagi umidlarni"}],full_uz:"Ammo qonlar yo‘lidagi umidlarni oqizib ketadi.",note:"جَرَفَ — oqizib, supurib ketmoq."},
{num:320,time:"00:34:59,599 --> 00:35:04,400",arabic:"وَيَبْقَى حَسِيسُ نَارِهَا يُؤَرِّقُ النَّاسَ جِيلًا بَعْدَ جِيلٍ.",segs:[{ar:"وَيَبْقَى حَسِيسُ نَارِهَا",uz:"Uning olovi shitirlashi davom etadi"},{ar:"يُؤَرِّقُ النَّاسَ",uz:"odamlarning uyqusini qochirib"},{ar:"جِيلًا بَعْدَ جِيلٍ",uz:"avloddan avlodga"}],full_uz:"Uning olovi shitirlashi avloddan avlodga odamlarning uyqusini qochirib turadi.",note:"حَسِيسٌ — past, sekin eshitiladigan tovush; جِيلًا بَعْدَ جِيلٍ — avloddan avlodga."},
{num:321,time:"00:35:04,400 --> 00:35:08,480",arabic:"لَا أَحْزَنَ اللَّهُ لَكِ قَلْبًا يَا أُمَّاهُ، فِدَاكِ نَفْسِي.",segs:[{ar:"لَا أَحْزَنَ اللَّهُ لَكِ قَلْبًا",uz:"Alloh qalbingizni g‘amga solmasin"},{ar:"يَا أُمَّاهُ",uz:"onajon"},{ar:"فِدَاكِ نَفْسِي",uz:"jonim sizga fido bo‘lsin"}],full_uz:"Alloh qalbingizni g‘amga solmasin, onajon. Jonim sizga fido bo‘lsin.",note:null},
{num:322,time:"00:35:08,480 --> 00:35:11,440",arabic:"إِنَّ قَدَرَ اللَّهِ مَاضٍ عَلَى خَلْقِهِ.",segs:[{ar:"إِنَّ قَدَرَ اللَّهِ مَاضٍ",uz:"Allohning taqdiri amalga oshuvchidir"},{ar:"عَلَى خَلْقِهِ",uz:"Uning yaratganlari ustida"}],full_uz:"Allohning taqdiri Uning yaratganlari ustida amalga oshadi.",note:"مَاضٍ bu yerda «o‘tgan» emas, «amalga oshadigan, kuchga ega» ma’nosida."},
{num:323,time:"00:35:11,440 --> 00:35:14,500",arabic:"لَا يَعْبَأُ بِأَمَانِي النَّاسِ وَلَا أَحْلَامِهِمْ.",segs:[{ar:"لَا يَعْبَأُ بِأَمَانِي النَّاسِ",uz:"Odamlarning istaklariga qaramaydi"},{ar:"وَلَا أَحْلَامِهِمْ",uz:"orzulariga ham"}],full_uz:"Odamlarning istak va orzulariga qaramaydi.",note:"عَبِئَ بِـ — ahamiyat bermoq, hisobga olmoq."},
{num:324,time:"00:35:14,500 --> 00:35:20,159",arabic:"وَإِنِّي لَأَحْمَدُ اللَّهَ أَنَّنِي خَرَجْتُ مِنْ هَذِهِ الدُّنْيَا...",segs:[{ar:"وَإِنِّي لَأَحْمَدُ اللَّهَ",uz:"Men Allohga hamd aytaman"},{ar:"أَنَّنِي خَرَجْتُ مِنْ هَذِهِ الدُّنْيَا",uz:"bu dunyodan ... bilan chiqqanim uchun"}],full_uz:"Bu dunyodan ... bilan chiqqanim uchun Allohga hamd aytaman.",note:"خَرَجَ مِنَ الدُّنْيَا بِـ bu yerda hayotdan olingan eng qadrli nasibani ifodalaydi; gap keyingi bandda tugaydi."},
{num:325,time:"00:35:20,159 --> 00:35:22,699",arabic:"بِوَلَدٍ مِثْلِكَ.",segs:null,full_uz:"Sizdek farzand bilan.",note:null},
{num:326,time:"00:35:22,699 --> 00:35:29,019",arabic:"فَأَنَا لَا أُرِيدُ مِنْ هَذِهِ الدُّنْيَا غَيْرَكَ يَا وَلَدِي.",segs:[{ar:"فَأَنَا لَا أُرِيدُ مِنْ هَذِهِ الدُّنْيَا",uz:"Men bu dunyodan istamayman"},{ar:"غَيْرَكَ يَا وَلَدِي",uz:"sizdan boshqasini, bolam"}],full_uz:"Men bu dunyodan sizdan boshqa narsani istamayman, bolam.",note:null},
{num:327,time:"00:35:29,019 --> 00:35:30,559",arabic:"أَطَالَ اللَّهُ عُمْرَكِ.",segs:null,full_uz:"Alloh umringizni uzoq qilsin.",note:null},
{num:328,time:"00:35:30,559 --> 00:35:33,219",arabic:"فَأَنْتِ شَرِيكَةٌ لِي فِي كُلِّ أَمْرِي.",segs:[{ar:"فَأَنْتِ شَرِيكَةٌ لِي",uz:"Siz menga sheriksiz"},{ar:"فِي كُلِّ أَمْرِي",uz:"har bir ishimda"}],full_uz:"Siz har bir ishimda menga sheriksiz.",note:null},
{num:329,time:"00:35:39,940 --> 00:35:42,360",arabic:"وَلَيْتَنِي أَسْتَطِيعُ أَنْ أُقَدِّمَ لَكِ...",segs:[{ar:"وَلَيْتَنِي أَسْتَطِيعُ",uz:"Qaniydi qodir bo‘lsam"},{ar:"أَنْ أُقَدِّمَ لَكِ",uz:"sizga taqdim etishga"}],full_uz:"Qaniydi sizga bera olsam...",note:null},
{num:330,time:"00:35:42,360 --> 00:35:44,599",arabic:"وَلَوْ جُزْءًا صَغِيرًا مِمَّا قَدَّمْتِهِ لِي.",segs:[{ar:"وَلَوْ جُزْءًا صَغِيرًا",uz:"hech bo‘lmasa kichik bir qismini"},{ar:"مِمَّا قَدَّمْتِهِ لِي",uz:"menga bergan narsalaringizning"}],full_uz:"Menga bergan narsalaringizning hech bo‘lmasa kichik bir qismini.",note:"وَلَوْ — «hech bo‘lmasa, hatto ... bo‘lsa ham»."},
{num:331,time:"00:35:44,599 --> 00:35:48,360",arabic:"يَكْفِي أَنْ أَرَاكَ أَمَامِي.",segs:[{ar:"يَكْفِي أَنْ أَرَاكَ",uz:"Sizni ko‘rishim kifoya"},{ar:"أَمَامِي",uz:"oldimda"}],full_uz:"Sizni oldimda ko‘rishim kifoya.",note:null},
{num:332,time:"00:35:48,360 --> 00:35:50,360",arabic:"وَلَدًا.",segs:null,full_uz:"Farzand sifatida.",note:null},
{num:333,time:"00:35:50,900 --> 00:35:52,360",arabic:"وَرَجُلًا.",segs:null,full_uz:"Va yetuk erkak sifatida.",note:null},
{num:334,time:"00:35:53,240 --> 00:35:57,360",arabic:"وَشَيْخًا يَمْلَأُ الْآفَاقَ عِلْمًا وَنُورًا.",segs:[{ar:"وَشَيْخًا",uz:"Va bir olim sifatida"},{ar:"يَمْلَأُ الْآفَاقَ",uz:"ufqlarni to‘ldiradigan"},{ar:"عِلْمًا وَنُورًا",uz:"ilm va nur bilan"}],full_uz:"Va ufqlarni ilm hamda nur bilan to‘ldiradigan olim sifatida.",note:"آفَاقٌ — أُفُقٌ («ufq») so‘zining ko‘pligi."},
{num:335,time:"00:35:58,900 --> 00:36:12,120",arabic:"اِغْفِرْ لِي قَوْلَ ذَلِكَ يَا مَوْلَايَ.",segs:[{ar:"اِغْفِرْ لِي قَوْلَ ذَلِكَ",uz:"Buni aytganimni kechiring"},{ar:"يَا مَوْلَايَ",uz:"hazratim"}],full_uz:"Buni aytganimni kechiring, hazratim.",note:null},
{num:336,time:"00:36:12,360 --> 00:36:15,420",arabic:"لَكِنَّ الْغَدْرَ جَاءَكَ مِنْ أَقْرَبِ النَّاسِ إِلَيْكَ.",segs:[{ar:"لَكِنَّ الْغَدْرَ جَاءَكَ",uz:"Ammo xiyonat sizga keldi"},{ar:"مِنْ أَقْرَبِ النَّاسِ إِلَيْكَ",uz:"eng yaqin kishilaringizdan"}],full_uz:"Ammo sizga eng yaqin kishilaringiz xiyonat qildi.",note:null},
{num:337,time:"00:36:15,420 --> 00:36:17,240",arabic:"فَهَرَبَ الْفَضْلُ بْنُ الرَّبِيعِ.",segs:null,full_uz:"Fazl ibn Rabi’ qochib ketdi.",note:null},
{num:338,time:"00:36:17,240 --> 00:36:19,720",arabic:"وَتَرَكَكَ وَحِيدًا تُوَاجِهُ الْمَصَاعِبَ.",segs:[{ar:"وَتَرَكَكَ وَحِيدًا",uz:"Sizni yolg‘iz qoldirdi"},{ar:"تُوَاجِهُ الْمَصَاعِبَ",uz:"qiyinchiliklarga yuzma-yuz"}],full_uz:"Sizni qiyinchiliklar bilan yolg‘iz yuzma-yuz qoldirdi.",note:null},
{num:339,time:"00:36:19,720 --> 00:36:23,519",arabic:"ثُمَّ مَا زَالَ الْقَوْمُ يَلْحَقُونَهُ خَائِنًا إِثْرَ خَائِنٍ.",segs:[{ar:"ثُمَّ مَا زَالَ الْقَوْمُ يَلْحَقُونَهُ",uz:"Keyin boshqalar ham uning ortidan ketishda davom etdi"},{ar:"خَائِنًا إِثْرَ خَائِنٍ",uz:"bir xoin ortidan boshqa xoin"}],full_uz:"Keyin boshqalar ham bir xoin ortidan boshqa xoin bo‘lib, uning ortidan ketaverdi.",note:"إِثْرَ — ortidan, ketidan."},
{num:340,time:"00:36:23,519 --> 00:36:26,300",arabic:"لَا تَقُلْ إِلَّا خَيْرًا عَنْ رِجَالِي يَا حَارِثُ.",segs:[{ar:"لَا تَقُلْ إِلَّا خَيْرًا",uz:"Faqat yaxshi gap ayting"},{ar:"عَنْ رِجَالِي",uz:"odamlarim haqida"},{ar:"يَا حَارِثُ",uz:"ey Horis"}],full_uz:"Odamlarim haqida faqat yaxshi gap ayting, Horis.",note:null},
{num:341,time:"00:36:26,300 --> 00:36:28,740",arabic:"فَمَا ظَنَنْتُ بِهِمْ إِلَّا الْخَيْرَ.",segs:null,full_uz:"Men ular haqida faqat yaxshi gumonda bo‘lganman.",note:"ظَنَّ بِهِ خَيْرًا — u haqida yaxshi gumonda bo‘lmoq."},
{num:342,time:"00:36:28,740 --> 00:36:33,800",arabic:"وَالطَّعْنُ بِوَلَائِهِمْ طَعْنٌ بِمَنِ اسْتَعْمَلَهُمْ.",segs:[{ar:"وَالطَّعْنُ بِوَلَائِهِمْ",uz:"Ularning sadoqatiga ta’na qilish"},{ar:"طَعْنٌ بِمَنِ اسْتَعْمَلَهُمْ",uz:"ularni tayinlagan kishiga ta’na qilishdir"}],full_uz:"Ularning sadoqatiga ta’na qilish ularni tayinlagan kishiga ta’na qilishdir.",note:"اِسْتَعْمَلَهُمْ bu yerda «ularni lavozimga yoki xizmatga tayinladi»."},
{num:343,time:"00:36:33,800 --> 00:36:38,360",arabic:"أَتَقُولُ فِيهِمْ ذَلِكَ رَغْمَ غَدْرِهِمْ يَا مَوْلَايَ؟",segs:[{ar:"أَتَقُولُ فِيهِمْ ذَلِكَ",uz:"Ular haqida shunday deysizmi"},{ar:"رَغْمَ غَدْرِهِمْ",uz:"xiyonatlariga qaramay"},{ar:"يَا مَوْلَايَ",uz:"hazratim?"}],full_uz:"Xiyonatlariga qaramay, ular haqida shunday deysizmi, hazratim?",note:null},
{num:344,time:"00:36:38,360 --> 00:36:44,000",arabic:"الْآنَ لَيْسَ أَوَانَ اللَّوْمِ يَا حَارِثُ.",segs:[{ar:"الْآنَ لَيْسَ أَوَانَ اللَّوْمِ",uz:"Hozir ayblash payti emas"},{ar:"يَا حَارِثُ",uz:"ey Horis"}],full_uz:"Hozir ayblash payti emas, Horis.",note:"أَوَانٌ — vaqt, payt."},
{num:345,time:"00:36:44,000 --> 00:36:45,440",arabic:"قُلْ لِي أَنْتَ.",segs:null,full_uz:"Siz o‘zingiz menga ayting.",note:null},
{num:346,time:"00:36:45,440 --> 00:36:47,900",arabic:"كَيْفَ انْتَهَى بِكَ الْحَالُ هُنَا؟",segs:null,full_uz:"Qanday qilib bu yerga tushib qoldingiz?",note:"اِنْتَهَى بِهِ الْحَالُ إِلَى — oxir-oqibat bir holatga yoki joyga kelib qolmoq."},
{num:347,time:"00:36:47,900 --> 00:36:49,780",arabic:"قَبَضُوا عَلَيَّ وَكَادُوا يَفْتِكُونَ بِي.",segs:[{ar:"قَبَضُوا عَلَيَّ",uz:"Meni qo‘lga olishdi"},{ar:"وَكَادُوا يَفْتِكُونَ بِي",uz:"va o‘ldirishlariga sal qoldi"}],full_uz:"Meni qo‘lga olishdi va o‘ldirishlariga sal qoldi.",note:"كَادَ + muzori’ — «...qilishiga sal qoldi»."},
{num:348,time:"00:36:49,780 --> 00:36:52,320",arabic:"وَلَكِنِ افْتَدَيْتُ نَفْسِي مِنْهُمْ بِالْمَالِ.",segs:[{ar:"وَلَكِنِ افْتَدَيْتُ نَفْسِي مِنْهُمْ",uz:"Ammo ulardan o‘zimni qutqarib oldim"},{ar:"بِالْمَالِ",uz:"pul berib"}],full_uz:"Ammo pul berib, ulardan o‘zimni qutqarib oldim.",note:"اِفْتَدَى نَفْسَهُ بِالْمَالِ — pul evaziga o‘zini qutqarib olmoq."},
{num:349,time:"00:36:52,320 --> 00:36:57,039",arabic:"إِنَّهُمْ عَبِيدُ الدِّرْهَمِ وَالدِّينَارِ.",segs:null,full_uz:"Ular dirham va dinorning qullari.",note:null},
{num:350,time:"00:36:57,039 --> 00:37:00,579",arabic:"يَبِيعُونَ الدُّنْيَا بِحَفْنَةِ دَرَاهِمَ.",segs:[{ar:"يَبِيعُونَ الدُّنْيَا",uz:"Dunyoni sotadilar"},{ar:"بِحَفْنَةِ دَرَاهِمَ",uz:"bir hovuch dirhamga"}],full_uz:"Dunyoni bir hovuch dirhamga sotadilar.",note:"حَفْنَةٌ — bir hovuch."},
{num:351,time:"00:37:00,579 --> 00:37:05,200",arabic:"فَيَا لَيْتَهُمْ يَقْبَلُونَ مِنِّي مَا قَبِلُوهُ مِنْكَ.",segs:[{ar:"فَيَا لَيْتَهُمْ يَقْبَلُونَ مِنِّي",uz:"Qaniydi mendan ham qabul qilsalar"},{ar:"مَا قَبِلُوهُ مِنْكَ",uz:"sizdan qabul qilgan narsalarini"}],full_uz:"Qaniydi sizdan qabul qilgan narsalarini mendan ham qabul qilsalar.",note:null},
{num:352,time:"00:37:05,199 --> 00:37:09,579",arabic:"لَنْ يَسْتَطِيعُوا لَكَ ضَرًّا يَا مَوْلَايَ.",segs:[{ar:"لَنْ يَسْتَطِيعُوا لَكَ ضَرًّا",uz:"Ular sizga zarar yetkaza olmaydilar"},{ar:"يَا مَوْلَايَ",uz:"hazratim"}],full_uz:"Ular sizga zarar yetkaza olmaydilar, hazratim.",note:null},
{num:353,time:"00:37:09,579 --> 00:37:16,099",arabic:"لَنْ يَرْضَى هَؤُلَاءِ الْعَبِيدُ إِلَّا بِقَتْلِي أَيُّهَا الْحَارِثُ.",segs:[{ar:"لَنْ يَرْضَى هَؤُلَاءِ الْعَبِيدُ",uz:"Bu qullar rozi bo‘lmaydilar"},{ar:"إِلَّا بِقَتْلِي",uz:"faqat meni o‘ldirish bilangina"},{ar:"أَيُّهَا الْحَارِثُ",uz:"ey Horis"}],full_uz:"Bu qullar meni o‘ldirishdan boshqa narsaga rozi bo‘lmaydilar, ey Horis.",note:null},
{num:354,time:"00:37:16,099 --> 00:37:19,759",arabic:"وَأَحْسَبُ أَنَّ سَوَادَ قُلُوبِهِمْ سَيُعْمِيهِمْ.",segs:[{ar:"وَأَحْسَبُ أَنَّ",uz:"O‘ylaymanki"},{ar:"سَوَادَ قُلُوبِهِمْ سَيُعْمِيهِمْ",uz:"qalblarining qoraligi ularni ko‘r qiladi"}],full_uz:"O‘ylaymanki, qalblarining qoraligi ularni ko‘r qiladi.",note:null},
{num:355,time:"00:37:19,759 --> 00:37:22,639",arabic:"فَلَا أَصِلُ إِلَى أَخِي الْمَأْمُونِ.",segs:[{ar:"فَلَا أَصِلُ",uz:"Shunda yetib borolmayman"},{ar:"إِلَى أَخِي الْمَأْمُونِ",uz:"birodarim Ma’munning oldiga"}],full_uz:"Shunda birodarim Ma’munning oldiga yetib borolmayman.",note:null},
{num:356,time:"00:39:35,199 --> 00:39:55,359",arabic:"تَأَمَّلْ يَا ابْنَ نُوحٍ.",segs:null,full_uz:"Tafakkur qiling, ey Ibn Nuh.",note:null},
{num:357,time:"00:39:55,359 --> 00:40:02,199",arabic:"إِلَى هَذِهِ الْحُفْرَةِ نَصِيرُ جَمِيعًا.",segs:[{ar:"إِلَى هَذِهِ الْحُفْرَةِ",uz:"Mana shu chuqurga"},{ar:"نَصِيرُ جَمِيعًا",uz:"hammamiz boramiz"}],full_uz:"Oxir-oqibat hammamiz mana shu chuqurga boramiz.",note:"صَارَ إِلَى — oxir-oqibat bir joyga yoki holatga yetmoq."},
{num:358,time:"00:40:05,199 --> 00:40:08,519",arabic:"السَّيِّدُ وَالْخَادِمُ عَلَى السَّوَاءِ.",segs:[{ar:"السَّيِّدُ وَالْخَادِمُ",uz:"Xo‘jayin ham, xizmatkor ham"},{ar:"عَلَى السَّوَاءِ",uz:"birdek"}],full_uz:"Xo‘jayin ham, xizmatkor ham birdek.",note:"عَلَى السَّوَاءِ — teng ravishda, birdek."},
{num:359,time:"00:40:08,519 --> 00:40:11,439",arabic:"مَا زِلْتَ تَفْتَقِدُهَا يَا أَبَا عَبْدِ اللَّهِ؟",segs:[{ar:"مَا زِلْتَ تَفْتَقِدُهَا",uz:"Uni hali ham sog‘inyapsizmi"},{ar:"يَا أَبَا عَبْدِ اللَّهِ",uz:"ey Abu Abdulloh?"}],full_uz:"Uni hali ham sog‘inyapsizmi, ey Abu Abdulloh?",note:"اِفْتَقَدَ — kimningdir yo‘qligini his qilmoq, sog‘inmoq."},
{num:360,time:"00:40:11,439 --> 00:40:17,639",arabic:"لَا يُفَارِقُنِي طَيْفُهَا يَا ابْنَ نُوحٍ.",segs:[{ar:"لَا يُفَارِقُنِي طَيْفُهَا",uz:"Uning siymosi meni tark etmaydi"},{ar:"يَا ابْنَ نُوحٍ",uz:"ey Ibn Nuh"}],full_uz:"Uning siymosi meni tark etmaydi, ey Ibn Nuh.",note:"طَيْفٌ — xayolda gavdalanadigan siymo, tasvir."},
{num:361,time:"00:40:17,639 --> 00:40:21,579",arabic:"كَانَتْ، رَحِمَهَا اللَّهُ...",segs:[{ar:"كَانَتْ",uz:"U edi"},{ar:"رَحِمَهَا اللَّهُ",uz:"Alloh uni rahmat qilsin"}],full_uz:"U — Alloh uni rahmat qilsin — ... edi.",note:null},
{num:362,time:"00:40:21,579 --> 00:40:24,579",arabic:"عَالَمِي كُلَّهُ.",segs:null,full_uz:"Butun dunyoyim.",note:"كُلَّهُ oldingi عَالَمِي so‘zini ta’kidlaydi: «butun dunyoyim»."},
{num:363,time:"00:40:24,579 --> 00:40:28,739",arabic:"لَمْ تَكُنْ أُمِّي فَقَطْ.",segs:null,full_uz:"U faqat onam emas edi.",note:null},
{num:364,time:"00:40:28,739 --> 00:40:32,199",arabic:"بَلْ كَانَتْ أَهْلِي جَمِيعًا.",segs:null,full_uz:"Balki butun oilam edi.",note:null},
{num:365,time:"00:40:35,199 --> 00:40:38,259",arabic:"تَغَمَّدَهَا اللَّهُ بِرَحْمَتِهِ.",segs:null,full_uz:"Alloh uni O‘z rahmatiga olsin.",note:"تَغَمَّدَهُ بِرَحْمَتِهِ — uni rahmati bilan qamrab olmoq; vafot etgan kishi uchun aytiladigan duo."},
{num:366,time:"00:40:38,259 --> 00:40:42,500",arabic:"رَحِمَهَا اللَّهُ يَا ابْنَ حَنْبَلٍ.",segs:null,full_uz:"Alloh uni rahmat qilsin, ey Ibn Hanbal.",note:null},
{num:367,time:"00:40:42,500 --> 00:40:44,199",arabic:"رَحِمَهَا اللَّهُ.",segs:null,full_uz:"Alloh uni rahmat qilsin.",note:null},
{num:368,time:"00:40:52,619 --> 00:40:55,759",arabic:"وَدِدْتُ لَوْ أَنَّنِي مِتُّ قَبْلَهَا يَا ابْنَ نُوحٍ.",segs:[{ar:"وَدِدْتُ لَوْ أَنَّنِي مِتُّ قَبْلَهَا",uz:"Qaniydi undan oldin vafot etgan bo‘lsam edi"},{ar:"يَا ابْنَ نُوحٍ",uz:"ey Ibn Nuh"}],full_uz:"Qaniydi undan oldin vafot etgan bo‘lsam edi, ey Ibn Nuh.",note:"وَدِدْتُ لَوْ — «qaniydi ... bo‘lsa edi, istardimki ...»."},
{num:369,time:"00:40:58,779 --> 00:41:04,659",arabic:"لَا نَقُولُ إِلَّا مَا يُرْضِي رَبَّنَا.",segs:[{ar:"لَا نَقُولُ إِلَّا",uz:"Faqat aytamiz"},{ar:"مَا يُرْضِي رَبَّنَا",uz:"Rabbimizni rozi qiladigan gapni"}],full_uz:"Faqat Rabbimizni rozi qiladigan gapni aytamiz.",note:"أَرْضَى — يُرْضِي: «rozi qilmoq»."},
{num:370,time:"00:41:04,659 --> 00:41:08,699",arabic:"إِنَّ لِلَّهِ مَا أَخَذَ.",segs:null,full_uz:"Albatta, Alloh olgan narsa Unikidir.",note:null},
{num:371,time:"00:41:08,699 --> 00:41:11,899",arabic:"وَلَهُ مَا أَعْطَى.",segs:null,full_uz:"Bergan narsasi ham Unikidir.",note:null},
{num:372,time:"00:41:20,159 --> 00:41:26,599",arabic:"هَوِّنْ عَلَيْكَ يَا ابْنَ حَنْبَلٍ.",segs:null,full_uz:"O‘zingizni buncha qiynamang, ey Ibn Hanbal.",note:"هَوِّنْ عَلَيْكَ — tasalli berish iborasi: «o‘zingizni bosib oling, ko‘nglingizni tinchlantiring»."},
{num:373,time:"00:41:26,599 --> 00:41:28,739",arabic:"فَمَنْ عَاشَ مَاتَ.",segs:[{ar:"فَمَنْ عَاشَ",uz:"Kim yashasa"},{ar:"مَاتَ",uz:"o‘ladi"}],full_uz:"Kim yashasa, o‘ladi.",note:"Fe’llar o‘tgan zamonda bo‘lsa ham, bu hikmatli gap umumiy haqiqatni bildiradi."},
{num:374,time:"00:41:28,739 --> 00:41:30,799",arabic:"وَمَنْ مَاتَ فَاتَ.",segs:[{ar:"وَمَنْ مَاتَ",uz:"Kim o‘lsa"},{ar:"فَاتَ",uz:"ketadi"}],full_uz:"Kim o‘lsa, bu dunyodan ketadi.",note:"فَاتَ — o‘tib ketmoq, qo‘ldan ketmoq; bu yerda dunyodan ketish ma’nosida."},
{num:375,time:"00:41:30,799 --> 00:41:33,539",arabic:"وَكُلُّ مَا هُوَ آتٍ آتٍ.",segs:[{ar:"وَكُلُّ مَا هُوَ آتٍ",uz:"Keladigan har bir narsa"},{ar:"آتٍ",uz:"albatta keladi"}],full_uz:"Keladigan har bir narsa albatta keladi.",note:"آتٍ — أَتَى — يَأْتِي fe’lidan yasalgan sifatdosh: «keluvchi»."},
{num:376,time:"00:41:33,539 --> 00:41:37,019",arabic:"إِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَيِّتُونَ.",segs:[{ar:"إِنَّكَ مَيِّتٌ",uz:"Albatta, siz vafot etuvchisiz"},{ar:"وَإِنَّهُمْ مَيِّتُونَ",uz:"ular ham vafot etuvchidirlar"}],full_uz:"Albatta, siz ham vafot etuvchisiz, ular ham vafot etuvchidirlar.",note:"مَيِّتٌ bu yerda allaqachon o‘lgan emas, kelajakda o‘ladigan kishi ma’nosida."},
{num:377,time:"00:41:37,019 --> 00:41:39,000",arabic:"وَنِعْمَ بِاللَّهِ.",segs:null,full_uz:"Alloh qanday ham yaxshi suyanch!",note:"وَنِعْمَ بِاللَّهِ — Allohni ulug‘lash va Unga ishonch bildirish iborasi."},
{num:378,time:"00:41:39,000 --> 00:41:42,719",arabic:"كِدْتَ تُنْسِينِي مَا جِئْتُ مِنْ أَجْلِهِ يَا أَحْمَدُ.",segs:[{ar:"كِدْتَ تُنْسِينِي",uz:"Menga deyarli unuttirib qo‘ydingiz"},{ar:"مَا جِئْتُ مِنْ أَجْلِهِ",uz:"nima uchun kelganimni"},{ar:"يَا أَحْمَدُ",uz:"ey Ahmad"}],full_uz:"Nima uchun kelganimni deyarli unuttirib qo‘ydingiz, Ahmad.",note:"أَنْسَى — يُنْسِي: «unuttirmoq». كِدْتَ — «sal qoldi, deyarli ... qildingiz»."},
{num:379,time:"00:41:42,719 --> 00:41:47,460",arabic:"خَيْرًا إِنْ شَاءَ اللَّهُ.",segs:null,full_uz:"Alloh xohlasa, yaxshilikdir.",note:null},
{num:380,time:"00:41:47,460 --> 00:41:50,860",arabic:"كُلُّ الْخَيْرِ بِإِذْنِ اللَّهِ يَا صَاحِبِي.",segs:[{ar:"كُلُّ الْخَيْرِ",uz:"Tamomila yaxshilik"},{ar:"بِإِذْنِ اللَّهِ",uz:"Allohning izni bilan"},{ar:"يَا صَاحِبِي",uz:"do‘stim"}],full_uz:"Allohning izni bilan, tamomila yaxshilik, do‘stim.",note:null},
{num:381,time:"00:41:50,860 --> 00:41:55,599",arabic:"أَرْسَلَنِي أَصْحَابُكَ مِنْ عُلَمَاءِ بَغْدَادَ وَفُقَهَائِهَا لِلْبَحْثِ عَنْكَ.",segs:[{ar:"أَرْسَلَنِي أَصْحَابُكَ",uz:"Meni do‘stlaringiz yuborishdi"},{ar:"مِنْ عُلَمَاءِ بَغْدَادَ وَفُقَهَائِهَا",uz:"Bag‘dod olimlari va faqihlaridan bo‘lgan"},{ar:"لِلْبَحْثِ عَنْكَ",uz:"sizni qidirish uchun"}],full_uz:"Bag‘dod olimlari va faqihlaridan bo‘lgan do‘stlaringiz meni sizni qidirishga yuborishdi.",note:null},
{num:382,time:"00:41:55,599 --> 00:41:59,239",arabic:"يُرِيدُونَ أَنْ يُبَارِكُوا لَكَ فِي مَوْلُودِكَ الْجَدِيدِ.",segs:[{ar:"يُرِيدُونَ أَنْ يُبَارِكُوا لَكَ",uz:"Sizni tabriklamoqchilar"},{ar:"فِي مَوْلُودِكَ الْجَدِيدِ",uz:"yangi tug‘ilgan farzandingiz bilan"}],full_uz:"Sizni yangi tug‘ilgan farzandingiz bilan tabriklamoqchilar.",note:"مَوْلُودٌ — yangi tug‘ilgan bola; وَلَدَ fe’lidan yasalgan."},
{num:383,time:"00:41:59,239 --> 00:42:00,539",arabic:"بَارَكَ اللَّهُ لَكَ فِيهِ.",segs:null,full_uz:"Alloh uni siz uchun barakali qilsin.",note:null},
{num:384,time:"00:42:00,539 --> 00:42:03,039",arabic:"بَارَكَ اللَّهُ فِيكَ وَفِيهِمْ.",segs:null,full_uz:"Alloh sizga ham, ularga ham baraka bersin.",note:null},
{num:385,time:"00:42:03,039 --> 00:42:05,719",arabic:"أَلَا نَذْهَبُ يَا ابْنَ حَنْبَلٍ؟",segs:null,full_uz:"Ketmaymizmi, ey Ibn Hanbal?",note:"أَلَا نَذْهَبُ؟ — birga ketishni taklif qilish: «ketmaymizmi, yursak-chi?»."},
{num:386,time:"00:42:05,719 --> 00:42:06,900",arabic:"فَالْقَوْمُ يَنْتَظِرُونَكَ.",segs:null,full_uz:"Axir ular sizni kutishyapti.",note:null}
];

if (typeof module !== "undefined" && module.exports) {
    module.exports = lessons;
}
